              <DollarSign className="text-primary mr-3" size={20} />
              <div className="text-left w-full">
                <label className="block text-xs text-gray-400 font-medium">Pricing</label>
                <select className="w-full bg-transparent text-dark font-medium focus:outline-none cursor-pointer appearance-none -ml-1">
                  <option>Choose Budget</option>
                  <option>₦ - Inexpensive</option>
                  <option>₦₦ - Moderate</option>
                  <option>₦₦₦ - Expensive</option>
