import { MOCK_BUSINESSES, MOCK_REVIEWS } from '../constants';
import { Star, MapPin, Phone, Mail, Globe, Share2, Heart, Clock, CheckCircle, Instagram, MessageCircle, Facebook, Twitter, Link as LinkIcon, Check } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import BusinessCard from '../components/BusinessCard';

const BusinessDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [showShareMenu, setShowShareMenu] = useState(false);
  const [copied, setCopied] = useState(false);

  const business = MOCK_BUSINESSES.find(b => b.id === id);

  if (!business) {
    return <div className="text-center py-20">Business not found</div>;
  }

  // Find related businesses in the same category, excluding current one
  const relatedBusinesses = MOCK_BUSINESSES
    .filter(b => b.category === business.category && b.id !== business.id)
    .slice(0, 4);

  const shareUrl = window.location.href;
  const shareText = `Check out ${business.name} on InstaConnect NG!`;

  const handleCopy = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => {
        setCopied(false);
        setShowShareMenu(false);
    }, 2000);
  };

  return (
    <div className="pb-20" onClick={() => showShareMenu && setShowShareMenu(false)}>
      {/* Header Info */}
      <div className="bg-white border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
             <div>
                <div className="flex items-center gap-3 mb-2">
                    <h1 className="text-3xl font-bold text-dark">{business.name}</h1>
                    <span className="bg-green-500 text-white text-xs font-bold px-2 py-1 rounded-md">{business.rating}</span>
                </div>
                <div className="flex flex-wrap items-center gap-4 text-sm text-graytext">
                   <div className="flex items-center gap-1">
                      {[...Array(5)].map((_, i) => (
                        <Star key={i} size={14} className={`${i < Math.floor(business.rating) ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'}`} />
                      ))}
                      <span className="ml-1">({business.reviewCount} reviews)</span>
                   </div>
                   <div className="flex items-center gap-1">
                      <MapPin size={14} className="text-primary" />
                      {business.location}
                   </div>
                   <div className="flex items-center gap-1">
                      <span className="text-primary font-semibold">{business.priceRange}</span>
                   </div>
                </div>
             </div>
             <div className="flex gap-3 relative z-20">
                <button className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 text-dark font-medium transition-colors">
                    <Heart size={18} /> Save
                </button>

                <div className="relative">
                    <button 
                        onClick={(e) => {
                            e.stopPropagation();
                            setShowShareMenu(!showShareMenu);
                        }}
                        className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-medium transition-colors ${showShareMenu ? 'bg-primary text-white border-primary' : 'bg-white border-gray-200 text-dark hover:bg-gray-50'}`}
                    >
                        <Share2 size={18} /> Share
                    </button>

                    {showShareMenu && (
                        <div className="absolute right-0 mt-2 w-56 bg-white rounded-xl shadow-xl border border-gray-100 p-2 animate-fade-in-up origin-top-right">
                            <div className="text-xs font-semibold text-gray-400 px-3 py-2 uppercase tracking-wider">Share via</div>

                            <a 
                                href={`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-3 px-3 py-2 text-dark hover:bg-blue-50 rounded-lg transition-colors text-sm font-medium"
                            >
                                <Facebook size={18} className="text-blue-600" /> Facebook
                            </a>

                            <a 
                                href={`https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(shareText)}`} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-3 px-3 py-2 text-dark hover:bg-sky-50 rounded-lg transition-colors text-sm font-medium"
                            >
                                <Twitter size={18} className="text-sky-500" /> Twitter
                            </a>

                            <a 
                                href={`https://wa.me/?text=${encodeURIComponent(shareText + ' ' + shareUrl)}`} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-3 px-3 py-2 text-dark hover:bg-green-50 rounded-lg transition-colors text-sm font-medium"
                            >
                                <MessageCircle size={18} className="text-green-500" /> WhatsApp
                            </a>

                            <div className="border-t border-gray-100 my-1"></div>

                            <button 
                                onClick={(e) => {
                                    e.stopPropagation();
                                    handleCopy();
                                }}
                                className="w-full flex items-center gap-3 px-3 py-2 text-dark hover:bg-gray-50 rounded-lg transition-colors text-left text-sm font-medium"
                            >
                                {copied ? <Check size={18} className="text-green-600" /> : <LinkIcon size={18} className="text-gray-400" />}
                                {copied ? 'Copied!' : 'Copy Link'}
                            </button>
                        </div>
                    )}
                </div>
             </div>
          </div>
        </div>
      </div>

      {/* Content Layout */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column (Main) */}
        <div className="lg:col-span-2 space-y-8">
            {/* Gallery */}
            <div className="rounded-2xl overflow-hidden shadow-lg h-96 relative">
                <img 
                  src={business.image} 
                  alt={business.name} 
                  loading="lazy"
                  className="w-full h-full object-cover" 
                />
                <div className="absolute bottom-4 right-4">
                    <button className="bg-white/90 backdrop-blur px-4 py-2 rounded-lg text-sm font-semibold hover:bg-white">View All Photos</button>
                </div>
            </div>

            {/* About */}
            <div className="glass-card p-6 rounded-2xl">
                <h3 className="text-xl font-bold text-dark mb-4">About Business</h3>
                <p className="text-graytext leading-relaxed mb-6">
                    {business.description}
                    <br/><br/>
                    Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.
                </p>

                <h4 className="font-semibold text-dark mb-3">Amenities</h4>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {business.tags.map((tag, i) => (
                        <div key={i} className="flex items-center gap-2 text-graytext text-sm">
                            <CheckCircle size={16} className="text-primary" />
                            {tag}
                        </div>
                    ))}
                </div>
            </div>

            {/* Reviews */}
            <div className="glass-card p-6 rounded-2xl">
                <h3 className="text-xl font-bold text-dark mb-6">Reviews</h3>
                <div className="space-y-6">
                    {MOCK_REVIEWS.map(review => (
                        <div key={review.id} className="border-b border-gray-100 last:border-0 pb-6 last:pb-0">
                            <div className="flex justify-between items-start mb-2">
                                <div className="flex items-center gap-3">
                                    <img 
                                      src={review.userImage} 
                                      alt={review.userName} 
                                      loading="lazy"
                                      className="w-10 h-10 rounded-full object-cover" 
                                    />
                                    <div>
                                        <h5 className="font-bold text-dark text-sm">{review.userName}</h5>
                                        <span className="text-xs text-gray-400">{review.date}</span>
                                    </div>
                                </div>
                                <div className="flex bg-yellow-400/10 px-2 py-1 rounded text-yellow-600 font-bold text-xs">
                                    <Star size={12} className="fill-yellow-600 mr-1" /> {review.rating}.0
                                </div>
                            </div>
                            <p className="text-graytext text-sm">{review.text}</p>
                        </div>
                    ))}
                </div>

                {user ? (
                   <form className="mt-8 border-t border-gray-100 pt-6">
                      <h4 className="font-semibold text-dark mb-4">Leave a Review</h4>
                      <div className="mb-4">
                         <textarea 
                           rows={3}
                           className="w-full bg-gray-50 rounded-xl p-4 text-sm border border-gray-200 focus:outline-none focus:border-primary transition-colors"
                           placeholder="Share your experience..."
                         ></textarea>
                      </div>
                      <button type="button" className="w-full sm:w-auto px-6 py-3 bg-primary text-white font-bold rounded-xl shadow-lg shadow-red-500/20 hover:bg-red-600 transition-all">
                        Post Review
                      </button>
                   </form>
                ) : (
                  <div className="mt-8 border-t border-gray-100 pt-6 text-center">
                    <p className="text-graytext mb-3">Please log in to leave a review.</p>
                    <Link to="/login" className="inline-block px-6 py-2 border border-primary text-primary font-semibold rounded-lg hover:bg-primary hover:text-white transition-all">
                       Log In
                    </Link>
                  </div>
                )}
            </div>
        </div>

        {/* Right Column (Sidebar) */}
        <div className="space-y-6">
            {/* Contact Card */}
            <div className="glass-card p-6 rounded-2xl sticky top-24">
                <h3 className="text-lg font-bold text-dark mb-4 border-b border-gray-100 pb-2">Contact Info</h3>

                <div className="space-y-4 mb-6">
                    <div className="flex items-start gap-3 text-graytext">
                        <MapPin className="mt-1 text-primary shrink-0" size={18} />
                        <span className="text-sm">{business.location}</span>
                    </div>
                    <div className="flex items-center gap-3 text-graytext">
                        <Phone className="text-primary shrink-0" size={18} />
                        <a href={`tel:${business.phone}`} className="text-sm hover:text-primary">{business.phone}</a>
                    </div>
                    <div className="flex items-center gap-3 text-graytext">
                        <Mail className="text-primary shrink-0" size={18} />
                        <a href={`mailto:${business.email}`} className="text-sm hover:text-primary">{business.email}</a>
                    </div>

                    {business.instagramHandle && (
                      <div className="flex items-center gap-3 text-graytext">
                          <Instagram className="text-primary shrink-0" size={18} />
                          <a href={`https://instagram.com/${business.instagramHandle}`} target="_blank" rel="noopener noreferrer" className="text-sm hover:text-primary">
                            @{business.instagramHandle}
                          </a>
                      </div>
                    )}

                    {business.whatsapp && (
                      <div className="flex items-center gap-3 text-graytext">
                          <MessageCircle className="text-primary shrink-0" size={18} />
                          <a href={`https://wa.me/${business.whatsapp.replace(/\+/g, '')}`} target="_blank" rel="noopener noreferrer" className="text-sm hover:text-primary">
                            Chat on WhatsApp
                          </a>
                      </div>
                    )}

                     <div className="flex items-center gap-3 text-graytext">
                        <Globe className="text-primary shrink-0" size={18} />
                        <a href="#" className="text-sm hover:text-primary">www.website.com</a>
                    </div>
                </div>

                <div className="mb-6">
                    <h4 className="font-semibold text-dark mb-2 text-sm flex items-center gap-2">
                        <Clock size={16} /> Opening Hours
                    </h4>
                    <div className="flex justify-between text-sm text-graytext mb-1">
                        <span>Monday - Friday</span>
                        <span>09:00 - 20:00</span>
                    </div>
                    <div className="flex justify-between text-sm text-graytext">
                        <span>Saturday - Sunday</span>
                        <span>10:00 - 22:00</span>
                    </div>
                </div>

                {business.whatsapp ? (
                   <a href={`https://wa.me/${business.whatsapp.replace(/\+/g, '')}`} target="_blank" rel="noopener noreferrer" className="block w-full text-center bg-green-500 hover:bg-green-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-green-500/30 transition-all mb-3 flex items-center justify-center gap-2">
                      <MessageCircle size={20} /> WhatsApp Us
                   </a>
                ) : (
                  <button className="w-full bg-primary hover:bg-red-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-red-500/30 transition-all mb-3">
                      Send Message
                  </button>
                )}

                 <a href={`tel:${business.phone}`} className="block w-full text-center bg-white border border-gray-200 text-dark font-bold py-3 rounded-xl hover:bg-gray-50 transition-all">
                    Call Now
                </a>
            </div>
        </div>
      </div>

      {/* Related Businesses / You Might Also Like */}
      {relatedBusinesses.length > 0 && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12 border-t border-gray-100 pt-12">
           <h3 className="text-2xl font-bold text-dark mb-6">You Might Also Like</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               {relatedBusinesses.map(b => (
                   <BusinessCard key={b.id} business={b} />
               ))}
           </div>
        </div>
      )}
    </div>
  );
};

export default BusinessDetail;

import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Calendar, MapPin, Grid, List, Clock, Search, Plus, Users, LayoutGrid } from 'lucide-react';
import { MOCK_EVENTS } from '../constants';
import { useAuth } from '../context/AuthContext';

const Events: React.FC = () => {
  const [viewMode, setViewMode] = useState<'grid' | 'list' | 'calendar'>('grid');
  const [searchTerm, setSearchTerm] = useState('');
  const { user } = useAuth();

  const filteredEvents = MOCK_EVENTS.filter(event => 
    event.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    event.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const CalendarView = () => {
    // Simplified Calendar View for demo
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const currentDate = new Date();
    // For demo purposes, we'll just show the current month November 2024 grid roughly
    // November 2024 starts on Friday (Day 5)

    return (
        <div className="glass-card p-6 rounded-2xl">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold text-dark">November 2024</h2>
                <div className="text-sm text-gray-400">Mock Calendar View</div>
            </div>
            <div className="grid grid-cols-7 gap-4 text-center mb-4">
                {days.map(day => <div key={day} className="font-bold text-gray-400 text-sm uppercase">{day}</div>)}
            </div>
            <div className="grid grid-cols-7 gap-4">
                {/* Empty slots for days before 1st */}
                {[...Array(5)].map((_, i) => <div key={`empty-${i}`} className="h-24 bg-gray-50/50 rounded-xl"></div>)}

                {/* Days 1-30 */}
                {[...Array(30)].map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2024-11-${day.toString().padStart(2, '0')}`;
                    const daysEvents = filteredEvents.filter(e => e.date === dateStr);

                    return (
                        <div key={day} className={`h-24 p-2 rounded-xl border border-gray-100 flex flex-col items-start justify-between hover:border-primary/30 transition-colors ${daysEvents.length > 0 ? 'bg-white shadow-sm' : 'bg-white/50'}`}>
                            <span className={`text-sm font-semibold ${daysEvents.length > 0 ? 'text-primary' : 'text-gray-400'}`}>{day}</span>
                            <div className="w-full space-y-1">
                                {daysEvents.map(event => (
                                    <Link to={`/event/${event.id}`} key={event.id} className="block w-full">
                                        <div className="text-[10px] bg-primary/10 text-primary px-1 py-0.5 rounded truncate font-medium">
                                            {event.time.split(' ')[0]} {event.title}
                                        </div>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
  };

  const GridView = () => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
      {filteredEvents.map(event => (
        <Link key={event.id} to={`/event/${event.id}`} className="group glass-card rounded-2xl overflow-hidden hover:shadow-xl transition-all hover:-translate-y-1">
          <div className="relative h-48">
            <img src={event.image} alt={event.title} className="w-full h-full object-cover" />
            <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1 rounded-lg text-xs font-bold text-dark shadow-sm">
              {event.category}
            </div>
            <div className="absolute bottom-4 left-4 bg-primary text-white px-3 py-1 rounded-lg text-xs font-bold shadow-sm">
                {event.price}
            </div>
          </div>
          <div className="p-5">
            <div className="flex text-xs font-bold text-primary mb-2 uppercase tracking-wide">
               {new Date(event.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })} • {event.time}
            </div>
            <h3 className="text-lg font-bold text-dark mb-2 group-hover:text-primary transition-colors line-clamp-1">{event.title}</h3>
            <div className="flex items-center text-graytext text-sm mb-4">
              <MapPin size={14} className="mr-1 text-gray-400" />
              <span className="truncate">{event.location}</span>
            </div>
            <div className="flex items-center justify-between border-t border-gray-100 pt-3">
                <div className="flex items-center text-xs text-gray-500 font-medium">
                    <Users size={14} className="mr-1" /> {event.attendees} going
                </div>
                <span className="text-sm font-bold text-dark group-hover:text-primary">View Details &rarr;</span>
            </div>
          </div>
        </Link>
      ))}
    </div>
  );

  const ListView = () => (
    <div className="space-y-4">
      {filteredEvents.map(event => (
        <Link key={event.id} to={`/event/${event.id}`} className="glass-card p-4 rounded-2xl flex flex-col md:flex-row gap-6 hover:shadow-lg transition-all group items-center">
           <div className="w-full md:w-48 h-32 rounded-xl overflow-hidden flex-shrink-0">
             <img src={event.image} alt={event.title} className="w-full h-full object-cover" />
           </div>
           <div className="flex-grow">
              <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-2">
                 <div>
                    <div className="text-xs font-bold text-primary mb-1 uppercase tracking-wide">
                        {new Date(event.date).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'long' })}
                    </div>
                    <h3 className="text-xl font-bold text-dark mb-2 group-hover:text-primary transition-colors">{event.title}</h3>
                    <div className="flex flex-col sm:flex-row gap-2 sm:gap-4 text-sm text-graytext">
                        <div className="flex items-center gap-1"><Clock size={14} /> {event.time}</div>
                        <div className="flex items-center gap-1"><MapPin size={14} /> {event.location}</div>
                    </div>
                 </div>
                 <div className="flex flex-row md:flex-col items-center md:items-end gap-2 mt-2 md:mt-0">
                    <span className="bg-primary/10 text-primary text-xs font-bold px-3 py-1 rounded-full">{event.category}</span>
                    <span className="font-bold text-dark">{event.price}</span>
                 </div>
              </div>
           </div>
        </Link>
      ))}
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
         <div>
            <h1 className="text-3xl font-bold text-dark mb-2">Discover Events</h1>
            <p className="text-graytext">Upcoming workshops, parties, and networking events.</p>
         </div>
         <Link to="/add-event" className="bg-primary hover:bg-red-600 text-white font-bold px-6 py-3 rounded-xl shadow-lg shadow-red-500/30 flex items-center gap-2 transition-colors">
             <Plus size={18} /> Host Event
         </Link>
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 mb-8 flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="relative w-full md:w-96">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search size={18} className="text-gray-400" />
              </div>
              <input 
                  type="text"
                  placeholder="Search events..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-primary w-full transition-all" 
              />
          </div>

          <div className="flex items-center gap-2 bg-gray-50 p-1 rounded-xl">
              <button 
                onClick={() => setViewMode('grid')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow text-primary' : 'text-gray-400 hover:text-dark'}`}
                title="Grid View"
              >
                  <Grid size={20} />
              </button>
              <button 
                onClick={() => setViewMode('list')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow text-primary' : 'text-gray-400 hover:text-dark'}`}
                title="List View"
              >
                  <List size={20} />
              </button>
              <button 
                onClick={() => setViewMode('calendar')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'calendar' ? 'bg-white shadow text-primary' : 'text-gray-400 hover:text-dark'}`}
                title="Calendar View"
              >
                  <Calendar size={20} />
              </button>
          </div>
      </div>

      {/* Content */}
      {viewMode === 'grid' && <GridView />}
      {viewMode === 'list' && <ListView />}
      {viewMode === 'calendar' && <CalendarView />}

      {filteredEvents.length === 0 && (
          <div className="text-center py-20 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-200">
              <p className="text-gray-500">No events found.</p>
          </div>
      )}
    </div>
  );
};

export default Events;

