import React, { useState } from 'react';
import { Star, ThumbsUp, Camera, MessageCircle, CornerDownRight } from 'lucide-react';
import { Review, User } from '../types';

// --- Rating Breakdown Component (Phase 2 Feature 5) ---
export const RatingBreakdown: React.FC<{ reviews: Review[] }> = ({ reviews }) => {
    const total = reviews.length;
    const counts = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };

    reviews.forEach(r => {
        const rating = Math.round(r.rating) as 1|2|3|4|5;
        if (counts[rating] !== undefined) counts[rating]++;
    });

    return (
        <div className="glass-card p-6 rounded-2xl mb-8">
            <h4 className="font-bold text-dark mb-4 text-lg">Rating Breakdown</h4>
            <div className="space-y-3">
                {[5, 4, 3, 2, 1].map(star => {
                    const count = counts[star as keyof typeof counts];
                    const percentage = total > 0 ? (count / total) * 100 : 0;
                    return (
                        <div key={star} className="flex items-center gap-3">
                            <div className="flex items-center w-12 gap-1 text-sm font-medium text-gray-600">
                                {star} <Star size={12} className="fill-gray-400 text-gray-400" />
                            </div>
                            <div className="flex-1 h-2.5 bg-gray-100 rounded-full overflow-hidden">
                                <div 
                                    className="h-full bg-yellow-400 rounded-full transition-all duration-500"
                                    style={{ width: `${percentage}%` }}
                                ></div>
                            </div>
                            <div className="w-10 text-xs text-gray-400 text-right">{Math.round(percentage)}%</div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// --- Review Form Component (Phase 1 Feature 2) ---
interface ReviewFormProps {
    onSubmit: (rating: number, text: string, photos: File[]) => void;
    user: User;
}

export const ReviewForm: React.FC<ReviewFormProps> = ({ onSubmit, user }) => {
    const [rating, setRating] = useState(0);
    const [text, setText] = useState('');
    const [hoveredRating, setHoveredRating] = useState(0);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (rating === 0) return alert('Please select a rating');
        onSubmit(rating, text, []); // Mocking photo upload as empty array for now
        setRating(0);
        setText('');
    };

    return (
        <div className="glass-card p-6 rounded-2xl mb-8 border border-primary/10 bg-primary/5">
            <h4 className="font-bold text-dark mb-4">Write a Review</h4>
            <form onSubmit={handleSubmit}>
                <div className="mb-4">
                    <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Rating</label>
                    <div className="flex gap-2">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button
                                type="button"
                                key={star}
                                onMouseEnter={() => setHoveredRating(star)}
                                onMouseLeave={() => setHoveredRating(0)}
                                onClick={() => setRating(star)}
                                className="focus:outline-none transition-transform hover:scale-110"
                            >
                                <Star 
                                    size={28} 
                                    className={`${star <= (hoveredRating || rating) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`} 
                                />
                            </button>
                        ))}
                    </div>
                </div>

                <div className="mb-4">
                    <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Review</label>
                    <textarea
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        rows={4}
                        placeholder="Share your experience with others..."
                        className="w-full bg-white rounded-xl p-4 text-sm border border-gray-200 focus:outline-none focus:border-primary transition-colors"
                        required
                    />
                </div>

                <div className="flex justify-between items-center">
                     {/* Photo Upload Trigger (Phase 2 Feature 6) */}
                    <button type="button" className="flex items-center gap-2 text-gray-500 hover:text-dark text-sm font-medium px-3 py-2 rounded-lg hover:bg-white transition-colors">
                        <Camera size={18} /> Add Photos
                    </button>

                    <button 
                        type="submit" 
                        disabled={!text || rating === 0}
                        className="bg-primary text-white font-bold px-6 py-2.5 rounded-xl shadow-lg shadow-red-500/20 hover:bg-red-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                        Post Review
                    </button>
                </div>
            </form>
        </div>
    );
};

// --- Review Card Component (Phase 1, 3, 4) ---
interface ReviewCardProps {
    review: Review;
    currentUser: User | null;
    isOwner: boolean;
}

export const ReviewCard: React.FC<ReviewCardProps> = ({ review, currentUser, isOwner }) => {
    const [liked, setLiked] = useState(false);
    const [likeCount, setLikeCount] = useState(review.helpfulCount);

    const handleLike = () => {
        if (liked) {
            setLikeCount(likeCount - 1);
        } else {
            setLikeCount(likeCount + 1);
        }
        setLiked(!liked);
    };

    return (
        <div className="glass-card p-6 rounded-2xl mb-6">
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <img 
                      src={review.userImage} 
                      alt={review.userName} 
                      className="w-10 h-10 rounded-full object-cover border border-gray-100" 
                    />
                    <div>
                        <h5 className="font-bold text-dark text-sm">{review.userName}</h5>
                        <span className="text-xs text-gray-400">{new Date(review.date).toLocaleDateString()}</span>
                    </div>
                </div>
                <div className="flex bg-yellow-50 px-2 py-1 rounded text-yellow-600 font-bold text-xs">
                    <Star size={12} className="fill-yellow-600 mr-1" /> {review.rating}.0
                </div>
            </div>

            <p className="text-graytext text-sm mb-4 leading-relaxed">{review.text}</p>

            {/* Review Photos (Phase 2) */}
            {review.photos && review.photos.length > 0 && (
                <div className="flex gap-2 mb-4 overflow-x-auto pb-2">
                    {review.photos.map((photo, i) => (
                        <img key={i} src={photo} alt="Review attachment" className="h-20 w-20 object-cover rounded-lg border border-gray-100" />
                    ))}
                </div>
            )}

            <div className="flex items-center gap-4 border-t border-gray-100 pt-4">
                {/* Helpful Vote (Phase 4 Feature 10) */}
                <button 
                    onClick={handleLike}
                    className={`flex items-center gap-1.5 text-xs font-bold transition-colors ${liked ? 'text-primary' : 'text-gray-400 hover:text-dark'}`}
                >
                    <ThumbsUp size={14} className={liked ? "fill-primary" : ""} /> 
                    Helpful ({likeCount})
                </button>

                {/* Vendor Reply Trigger (Phase 3 Feature 7 - Placeholder) */}
                {isOwner && !review.reply && (
                    <button className="flex items-center gap-1.5 text-xs font-bold text-gray-400 hover:text-primary transition-colors">
                        <MessageCircle size={14} /> Reply
                    </button>
                )}
            </div>

            {/* Vendor Reply Display (Phase 3) */}
            {review.reply && (
                <div className="mt-4 bg-gray-50 rounded-xl p-4 ml-4 border-l-2 border-primary">
                    <div className="flex items-center gap-2 mb-1">
                        <CornerDownRight size={14} className="text-gray-400" />
                        <span className="text-xs font-bold text-dark">Response from Owner</span>
                        <span className="text-[10px] text-gray-400">• {new Date(review.reply.date).toLocaleDateString()}</span>
                    </div>
                    <p className="text-xs text-gray-600">{review.reply.text}</p>
                </div>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { MOCK_BUSINESSES, MOCK_REVIEWS } from '../constants';
import { Star, MapPin, Phone, Mail, Globe, Share2, Heart, Clock, CheckCircle, Instagram, MessageCircle, Facebook, Twitter, Link as LinkIcon, Check, Filter, ArrowUpDown } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import BusinessCard from '../components/BusinessCard';
import { ReviewForm, RatingBreakdown, ReviewCard } from '../components/ReviewSystem';
import { Review } from '../types';

const BusinessDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [showShareMenu, setShowShareMenu] = useState(false);
  const [copied, setCopied] = useState(false);

  // Review System State
  const [sortBy, setSortBy] = useState<'recent' | 'highest' | 'lowest'>('recent');
  const [filterRating, setFilterRating] = useState<number | 'all'>('all');

  const business = MOCK_BUSINESSES.find(b => b.id === id);

  // Mock Reviews - Fetch reviews for this business
  const [reviews, setReviews] = useState<Review[]>(
      MOCK_REVIEWS.filter(r => r.businessId === id)
  );

  if (!business) {
    return <div className="text-center py-20">Business not found</div>;
  }

  // Filter and Sort Reviews
  const getProcessedReviews = () => {
      let filtered = reviews;

      if (filterRating !== 'all') {
          filtered = filtered.filter(r => Math.floor(r.rating) === filterRating);
      }

      return filtered.sort((a, b) => {
          if (sortBy === 'highest') return b.rating - a.rating;
          if (sortBy === 'lowest') return a.rating - b.rating;
          // default recent
          return new Date(b.date).getTime() - new Date(a.date).getTime();
      });
  };

  const processedReviews = getProcessedReviews();

  const handleReviewSubmit = (rating: number, text: string, photos: File[]) => {
      const newReview: Review = {
          id: Math.random().toString(),
          businessId: business.id,
          userId: user?.id || 'guest',
          userName: user?.name || 'Guest User',
          userImage: user?.image || 'https://ui-avatars.com/api/?name=Guest',
          rating: rating,
          date: new Date().toISOString(),
          text: text,
          helpfulCount: 0,
          photos: [] // In a real app, we'd handle file uploads here
      };
      setReviews([newReview, ...reviews]);
  };

  // Find related businesses in the same category, excluding current one
  const relatedBusinesses = MOCK_BUSINESSES
    .filter(b => b.category === business.category && b.id !== business.id)
    .slice(0, 4);

  const shareUrl = window.location.href;
  const shareText = `Check out ${business.name} on InstaConnect NG!`;

  const handleCopy = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => {
        setCopied(false);
        setShowShareMenu(false);
    }, 2000);
  };

  return (
    <div className="pb-20" onClick={() => showShareMenu && setShowShareMenu(false)}>
      {/* Header Info */}
      <div className="bg-white border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
             <div>
                <div className="flex items-center gap-3 mb-2">
                    <h1 className="text-3xl font-bold text-dark">{business.name}</h1>
                    <span className="bg-green-500 text-white text-xs font-bold px-2 py-1 rounded-md">{business.rating}</span>
                </div>
                <div className="flex flex-wrap items-center gap-4 text-sm text-graytext">
                   <div className="flex items-center gap-1">
                      {[...Array(5)].map((_, i) => (
                        <Star key={i} size={14} className={`${i < Math.floor(business.rating) ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'}`} />
                      ))}
                      <span className="ml-1">({business.reviewCount} reviews)</span>
                   </div>
                   <div className="flex items-center gap-1">
                      <MapPin size={14} className="text-primary" />
                      {business.location}
                   </div>
                   <div className="flex items-center gap-1">
                      <span className="text-primary font-semibold">{business.priceRange}</span>
                   </div>
                </div>
             </div>
             <div className="flex gap-3 relative z-20">
                <button className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 text-dark font-medium transition-colors">
                    <Heart size={18} /> Save
                </button>

                <div className="relative">
                    <button 
                        onClick={(e) => {
                            e.stopPropagation();
                            setShowShareMenu(!showShareMenu);
                        }}
                        className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-medium transition-colors ${showShareMenu ? 'bg-primary text-white border-primary' : 'bg-white border-gray-200 text-dark hover:bg-gray-50'}`}
                    >
                        <Share2 size={18} /> Share
                    </button>

                    {showShareMenu && (
                        <div className="absolute right-0 mt-2 w-56 bg-white rounded-xl shadow-xl border border-gray-100 p-2 animate-fade-in-up origin-top-right">
                            <div className="text-xs font-semibold text-gray-400 px-3 py-2 uppercase tracking-wider">Share via</div>

                            <a 
                                href={`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-3 px-3 py-2 text-dark hover:bg-blue-50 rounded-lg transition-colors text-sm font-medium"
                            >
                                <Facebook size={18} className="text-blue-600" /> Facebook
                            </a>

                            <a 
                                href={`https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(shareText)}`} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-3 px-3 py-2 text-dark hover:bg-sky-50 rounded-lg transition-colors text-sm font-medium"
                            >
                                <Twitter size={18} className="text-sky-500" /> Twitter
                            </a>

                            <a 
                                href={`https://wa.me/?text=${encodeURIComponent(shareText + ' ' + shareUrl)}`} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-3 px-3 py-2 text-dark hover:bg-green-50 rounded-lg transition-colors text-sm font-medium"
                            >
                                <MessageCircle size={18} className="text-green-500" /> WhatsApp
                            </a>

                            <div className="border-t border-gray-100 my-1"></div>

                            <button 
                                onClick={(e) => {
                                    e.stopPropagation();
                                    handleCopy();
                                }}
                                className="w-full flex items-center gap-3 px-3 py-2 text-dark hover:bg-gray-50 rounded-lg transition-colors text-left text-sm font-medium"
                            >
                                {copied ? <Check size={18} className="text-green-600" /> : <LinkIcon size={18} className="text-gray-400" />}
                                {copied ? 'Copied!' : 'Copy Link'}
                            </button>
                        </div>
                    )}
                </div>
             </div>
          </div>
        </div>
      </div>

      {/* Content Layout */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column (Main) */}
        <div className="lg:col-span-2 space-y-8">
            {/* Gallery */}
            <div className="rounded-2xl overflow-hidden shadow-lg h-96 relative">
                <img 
                  src={business.image} 
                  alt={business.name} 
                  loading="lazy"
                  className="w-full h-full object-cover" 
                />
                <div className="absolute bottom-4 right-4">
                    <button className="bg-white/90 backdrop-blur px-4 py-2 rounded-lg text-sm font-semibold hover:bg-white">View All Photos</button>
                </div>
            </div>

            {/* About */}
            <div className="glass-card p-6 rounded-2xl">
                <h3 className="text-xl font-bold text-dark mb-4">About Business</h3>
                <p className="text-graytext leading-relaxed mb-6">
                    {business.description}
                    <br/><br/>
                    Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.
                </p>

                <h4 className="font-semibold text-dark mb-3">Amenities</h4>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {business.tags.map((tag, i) => (
                        <div key={i} className="flex items-center gap-2 text-graytext text-sm">
                            <CheckCircle size={16} className="text-primary" />
                            {tag}
                        </div>
                    ))}
                </div>
            </div>

            {/* Reviews Section */}
            <div id="reviews">
                <h3 className="text-2xl font-bold text-dark mb-6 flex items-center gap-2">
                    Reviews <span className="text-gray-400 text-lg font-medium">({reviews.length})</span>
                </h3>

                {/* Rating Breakdown & Stats */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                    <div className="glass-card p-6 rounded-2xl flex flex-col items-center justify-center">
                        <div className="text-5xl font-black text-dark mb-2">{business.rating}</div>
                        <div className="flex gap-1 mb-2">
                             {[...Array(5)].map((_, i) => (
                                <Star key={i} size={20} className={`${i < Math.floor(business.rating) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`} />
                             ))}
                        </div>
                        <p className="text-gray-500 text-sm">Overall Rating</p>
                    </div>
                    <RatingBreakdown reviews={reviews} />
                </div>

                {/* Review Form */}
                {user ? (
                    <ReviewForm user={user} onSubmit={handleReviewSubmit} />
                ) : (
                    <div className="bg-gray-50 p-6 rounded-2xl text-center mb-8 border border-gray-100">
                        <p className="text-dark font-medium mb-3">Share your experience with this business</p>
                        <Link to="/login" className="inline-block bg-white border border-gray-200 px-6 py-2.5 rounded-xl text-primary font-bold shadow-sm hover:shadow-md transition-all">
