                    </div>
                </div>

                {/* Review List */}
                {processedReviews.length > 0 ? (
                    processedReviews.map(review => (
                        <ReviewCard 
                            key={review.id} 
                            review={review} 
                            currentUser={user}
                            isOwner={user?.role === 'vendor' && user?.id === business.ownerId}
                        />
