        </div>

        {/* Right Column (Sidebar) */}
        <div className="space-y-6">
            {/* Contact Card */}
            <div className="glass-card p-6 rounded-2xl sticky top-24">
                <h3 className="text-lg font-bold text-dark mb-4 border-b border-gray-100 pb-2">Contact Info</h3>

