                    <div className="flex items-center gap-3 text-graytext">
                        <Mail className="text-primary shrink-0" size={18} />
                        <a href={`mailto:${business.email}`} className="text-sm hover:text-primary">{business.email}</a>
                    </div>

                    {business.instagramHandle && (
                      <div className="flex items-center gap-3 text-graytext">
                          <Instagram className="text-primary shrink-0" size={18} />
                          <a href={`https://instagram.com/${business.instagramHandle}`} target="_blank" rel="noopener noreferrer" className="text-sm hover:text-primary">
                            @{business.instagramHandle}
                          </a>
                      </div>
                    )}

                    {business.whatsapp && (
                      <div className="flex items-center gap-3 text-graytext">
                          <MessageCircle className="text-primary shrink-0" size={18} />
                          <a href={`https://wa.me/${business.whatsapp.replace(/\+/g, '')}`} target="_blank" rel="noopener noreferrer" className="text-sm hover:text-primary">
                            Chat on WhatsApp
                          </a>
                      </div>
                    )}

                     <div className="flex items-center gap-3 text-graytext">
                        <Globe className="text-primary shrink-0" size={18} />
                        <a href="#" className="text-sm hover:text-primary">www.website.com</a>
                    </div>
                </div>

                <div className="mb-6">
                    <h4 className="font-semibold text-dark mb-2 text-sm flex items-center gap-2">
                        <Clock size={16} /> Opening Hours
                    </h4>
                    <div className="flex justify-between text-sm text-graytext mb-1">
                        <span>Monday - Friday</span>
                        <span>09:00 - 20:00</span>
                    </div>
                    <div className="flex justify-between text-sm text-graytext">
                        <span>Saturday - Sunday</span>
                        <span>10:00 - 22:00</span>
                    </div>
                </div>

                {business.whatsapp ? (
                   <a href={`https://wa.me/${business.whatsapp.replace(/\+/g, '')}`} target="_blank" rel="noopener noreferrer" className="block w-full text-center bg-green-500 hover:bg-green-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-green-500/30 transition-all mb-3 flex items-center justify-center gap-2">
                      <MessageCircle size={20} /> WhatsApp Us
                   </a>
                ) : (
                  <button className="w-full bg-primary hover:bg-red-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-red-500/30 transition-all mb-3">
                      Send Message
                  </button>
                )}

                 <a href={`tel:${business.phone}`} className="block w-full text-center bg-white border border-gray-200 text-dark font-bold py-3 rounded-xl hover:bg-gray-50 transition-all">
                    Call Now
                </a>
            </div>
        </div>
      </div>

      {/* Related Businesses / You Might Also Like */}
      {relatedBusinesses.length > 0 && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12 border-t border-gray-100 pt-12">
           <h3 className="text-2xl font-bold text-dark mb-6">You Might Also Like</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               {relatedBusinesses.map(b => (
                   <BusinessCard key={b.id} business={b} />
               ))}
           </div>
        </div>
      )}
    </div>
  );
};

