import React, { createContext, useContext, useState, useEffect } from 'react';
import { User } from '../types';
import { MOCK_USER } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (email: string, pass: string) => Promise<void>;
  register: (name: string, email: string, pass: string, role: 'consumer' | 'vendor') => Promise<void>;
  logout: () => void;
  updateCredits: (amount: number) => void;
  isLoading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Check local storage for persistent auth (mocking)
    const storedUser = localStorage.getItem('insta_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setIsLoading(false);
  }, []);

  const login = async (email: string, pass: string) => {
    // Mock login delay
    await new Promise(resolve => setTimeout(resolve, 800));
    // In a real app, validate credentials here
    const newUser: User = { ...MOCK_USER, email }; 
    setUser(newUser);
    localStorage.setItem('insta_user', JSON.stringify(newUser));
  };

  const register = async (name: string, email: string, pass: string, role: 'consumer' | 'vendor') => {
    // Mock register delay
    await new Promise(resolve => setTimeout(resolve, 800));
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      email,
      image: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=random`,
      role: role,
      credits: 0,
      badges: [],
      reputationPoints: 0,
      referralCode: Math.random().toString(36).substr(2, 8).toUpperCase(),
      referralCount: 0
    };
    setUser(newUser);
    localStorage.setItem('insta_user', JSON.stringify(newUser));
  };

  const updateCredits = (amount: number) => {
    if (user) {
      const updatedUser = { ...user, credits: user.credits + amount };
      setUser(updatedUser);
      localStorage.setItem('insta_user', JSON.stringify(updatedUser));
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('insta_user');
  };

  return (
    <AuthContext.Provider value={{ user, login, register, logout, updateCredits, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

