                 <a 
                    href={`tel:${business.phone}`} 
                    onClick={() => handleContactClick('call_click')}
                    className="block w-full text-center bg-white border border-gray-200 text-dark font-bold py-3 rounded-xl hover:bg-gray-50 transition-all"
