import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { MOCK_BUSINESSES } from '../constants';
import { Business, DailyMetric } from '../types';
import { 
  TrendingUp, Users, Star, CreditCard, Zap, Plus, X, Check, MapPin, 
  ExternalLink, Calendar, BarChart2, Edit, MessageSquare, Settings, ArrowRight
} from 'lucide-react';
import { analyticsService } from '../services/analytics';

const BusinessDashboard: React.FC = () => {
  const { user, isLoading, updateCredits } = useAuth();
  const navigate = useNavigate();
  const [myBusiness, setMyBusiness] = useState<Business | undefined>(undefined);
  const [metrics, setMetrics] = useState<DailyMetric[]>([]);
  const [showPromoteModal, setShowPromoteModal] = useState(false);
  const [showTopUpModal, setShowTopUpModal] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<'7' | '30' | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (!isLoading) {
      if (!user) {
        navigate('/login');
      } else if (user.role !== 'vendor') {
        navigate('/');
      } else {
        // Find business owned by user
        const business = MOCK_BUSINESSES.find(b => b.ownerId === user.id);
        setMyBusiness(business);

        if (business) {
            // Load stats
            const stats = analyticsService.getBusinessMetrics(business.id, 7);
            setMetrics(stats);
        }
      }
    }
  }, [user, isLoading, navigate]);

  const handleTopUp = (amount: number, cost: number) => {
    setIsProcessing(true);
    // Simulate Paystack Payment
    setTimeout(() => {
        setIsProcessing(false);
        updateCredits(amount);
        setShowTopUpModal(false);
        alert(`Payment of ₦${cost} successful! ${amount} credits added to your wallet.`);
    }, 2000);
  };

  const handlePromote = () => {
    if (!selectedPlan || !user) return;

    const cost = selectedPlan === '7' ? 100 : 300;

    if (user.credits < cost) {
        alert("Insufficient credits! Please top up your wallet.");
        setShowTopUpModal(true);
        setShowPromoteModal(false);
        return;
    }

    if (window.confirm(`Promote for ${cost} credits?`)) {
        updateCredits(-cost);
        setShowPromoteModal(false);
        alert(`Success! Your business is now promoted for ${selectedPlan} days.`);
    }
  };

  // Calculate totals from metrics (last 7 days)
