Ccomprehensive, step-by-step guide to building a robust admin access system and a holistic analytics dashboard for the business directory


***

### **Guide: Building the "Aether" Admin Dashboard & Analytics Hub**

**Objective:** To create a secure, role-based admin access system and a comprehensive analytics dashboard for monitoring the health, growth, and engagement of the "Aether" community.

---

### **Phase 1: Foundation - Implementing Role-Based Access Control (RBAC)**

Before you can build a dashboard, you must define who an admin is and secure the routes they will use.

1.  **Update the Database Schema:**
    *   In `apps/backend/prisma/schema.prisma`, modify the `User` model to include a `role` field.
    *   Define an `enum` for the possible roles.

    ```prisma
    // apps/backend/prisma/schema.prisma

    enum Role {
      USER
      MODERATOR
      ADMIN
    }

    model User {
      id            Int      @id @default(autoincrement())
      // ... other fields
      role          Role     @default(USER)
      // ...
    }
    ```
    *   Run the migration: `npx prisma migrate dev --name add-user-roles`.
    *   Manually update your own user record in the database to have the `ADMIN` role for initial testing.

2.  **Create an Admin Guard in the Backend:**
    *   In `apps/backend`, generate a new guard: `nest g guard admin --no-spec`.
    *   This guard will check if the authenticated user's JWT token contains the `ADMIN` role.

    ```typescript
    // apps/backend/src/auth/admin.guard.ts

    import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
    import { Reflector } from '@nestjs/core';
    import { ROLES_KEY } from './roles.decorator'; // We'll create this next

    @Injectable()
    export class AdminGuard implements CanActivate {
      constructor(private reflector: Reflector) {}

      canActivate(context: ExecutionContext): boolean {
        const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
          context.getHandler(),
          context.getClass(),
        ]);
        if (!requiredRoles) {
          return true;
        }
        const { user } = context.switchToHttp().getRequest();
        return requiredRoles.some((role) => user.role === role);
      }
    }
    ```
    *   Create a corresponding decorator: `apps/backend/src/auth/roles.decorator.ts`.

    ```typescript
    import { SetMetadata } from '@nestjs/common';
    import { Role } from '@prisma/client';

    export const ROLES_KEY = 'roles';
    export const Roles = (...roles: Role[]) => SetMetadata(ROLES_KEY, roles);
    ```

3.  **Secure Admin API Endpoints:**
    *   Apply the new `AdminGuard` to any controller or endpoint that should be admin-only.

    ```typescript
    // apps/backend/src/analytics/analytics.controller.ts

    import { Controller, Get, UseGuards } from '@nestjs/common';
    import { JwtAuthGuard } from '../auth/jwt-auth.guard';
    import { AdminGuard } from '../auth/admin.guard';
    import { Roles } from '../auth/roles.decorator';
    import { Role } from '@prisma/client';

    @Controller('admin/analytics')
    @UseGuards(JwtAuthGuard, AdminGuard) // Apply both guards
    @Roles(Role.ADMIN) // Specify the required role
    export class AnalyticsController {
      // ... all analytics endpoints will be here
    }
    ```

4.  **Update Frontend Session Management:**
    *   In `apps/frontend`, modify the NextAuth.js callbacks to include the user's role in the session token and session object.

    ```typescript
    // pages/api/auth/[...nextauth].ts

    callbacks: {
      async jwt({ token, user }) {
        if (user) {
          token.role = user.role; // Add role to token
        }
        return token;
      },
      async session({ session, token }) {
        if (token) {
          session.user.id = token.id;
          session.user.role = token.role; // Add role to session
        }
        return session;
      },
    },
    ```

---

### **Phase 2: The Analytics Backend - Data Collection & Aggregation**

Directly querying the main database for complex analytics can be slow. A more robust approach is to pre-calculate and store key metrics in a separate table.

1.  **Create Analytics Tables:**
    *   Add new models to your `schema.prisma` for storing aggregated data.

    ```prisma
    // apps/backend/prisma/schema.prisma

    model DailyAnalytics {
      date                DateTime @id @db.Date
      totalUsers          Int      @default(0)
      newUsers            Int      @default(0)
      activeUsers         Int      @default(0) // DAU
      totalPosts          Int      @default(0)
      totalComments       Int      @default(0)
      totalVotes          Int      @default(0)
      newEvents           Int      @default(0)
      totalEventAttendees Int      @default(0)
      // ... other metrics
    }

    model PageView {
      id          Int      @id @default(autoincrement())
      sessionId   String
      path        String
      timestamp   DateTime @default(now())
      userId      Int?     @map("user_id")
      user        User?    @relation(fields: [userId], references: [id], onDelete: SetNull)
      // We'll use this for session and bounce rate tracking
    }
    ```
    *   Run the migration: `npx prisma migrate dev --name add-analytics-tables`.

2.  **Implement a Data Tracking Endpoint:**
    *   Create a new public API endpoint `/api/analytics/track` to receive data from the frontend.

    ```typescript
    // apps/backend/src/analytics/analytics.controller.ts

    @Controller('analytics')
    export class AnalyticsController {
      // ... (admin controller is separate)

      @Post('track')
      async trackPageView(@Body() body: { path: string; sessionId: string }, @Req() req: Request) {
        const userId = req.user?.id; // Get user ID if logged in
        await this.prisma.pageView.create({
          data: {
            path: body.path,
            sessionId: body.sessionId,
            userId: userId,
          },
        });
        return { status: 'tracked' };
      }
    }
