3.  **Create a Daily Aggregation Cron Job:**
    *   This is the core of the analytics engine. A background job will run every day to calculate metrics and populate the `DailyAnalytics` table.

    ```typescript
    // apps/backend/src/analytics/analytics.service.ts

    import { Injectable, Logger } from '@nestjs/common';
    import { Cron, CronExpression } from '@nestjs/schedule';
    import { PrismaService } from '../prisma/prisma.service';

    @Injectable()
    export class AnalyticsService {
      private readonly logger = new Logger(AnalyticsService.name);

      constructor(private prisma: PrismaService) {}

      @Cron(CronExpression.EVERY_DAY_AT_MIDNIGHT)
      async handleDailyAggregation() {
        this.logger.log('Running daily analytics aggregation...');
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayStart = new Date(yesterday.setHours(0, 0, 0, 0));
        const yesterdayEnd = new Date(yesterday.setHours(23, 59, 59, 999));

        const totalUsers = await this.prisma.user.count();
        const newUsers = await this.prisma.user.count({
          where: { createdAt: { gte: yesterdayStart, lte: yesterdayEnd } },
        });
        // ... repeat for other metrics (posts, comments, etc.) for that day

        await this.prisma.dailyAnalytics.upsert({
          where: { date: yesterdayStart },
          update: {
            totalUsers,
            newUsers,
            // ... other metrics
          },
          create: {
            date: yesterdayStart,
            totalUsers,
            newUsers,
            // ... other metrics
          },
        });

        this.logger.log('Daily analytics aggregation complete.');
      }
    }
    ```

4.  **Create Admin API Endpoints for the Dashboard:**
    *   In the protected `AnalyticsController`, create endpoints to fetch the aggregated data for the dashboard.

