                                ))}
                                {!searchTerm && (
                                    <div className="text-center text-gray-400 text-sm py-8 bg-gray-50/50 rounded-xl border border-dashed border-gray-100">
                                        Start typing to find the business you want to review.
                                    </div>
                                )}
