// --- Review Card Component (Phase 1, 3, 4) ---
interface ReviewCardProps {
    review: Review;
    currentUser: User | null;
    isOwner: boolean;
}

export const ReviewCard: React.FC<ReviewCardProps> = ({ review, currentUser, isOwner }) => {
    const navigate = useNavigate();
    const [liked, setLiked] = useState(false);
    const [likeCount, setLikeCount] = useState(review.helpfulCount);
    const [isReported, setIsReported] = useState(false);

    // Mock finding user to get badges
    const reviewUser = MOCK_USERS_LIST.find(u => u.id === review.userId) || { badges: [] };
    const isReviewAuthor = currentUser?.id === review.userId;

    const handleLike = () => {
        if (!currentUser) {
            if (window.confirm("Please log in to vote on reviews. Go to login?")) {
                navigate('/login');
            }
            return;
        }

        if (isReviewAuthor) {
            return; // Prevent self-voting logic handled by disabled state, double check here
        }

        if (liked) {
            setLikeCount(prev => prev - 1);
        } else {
            setLikeCount(prev => prev + 1);
        }
        setLiked(!liked);
    };

    const handleReport = () => {
        if (!currentUser) {
             if (window.confirm("Please log in to report content. Go to login?")) {
                navigate('/login');
            }
            return;
        }

        if (window.confirm("Report this review as inappropriate?")) {
            setIsReported(true);
            alert("Review flagged for moderation.");
        }
    };

    if (review.status === 'hidden' && currentUser?.role !== 'admin') return null;

    return (
        <div className={`glass-card p-6 rounded-2xl mb-6 relative ${review.status === 'flagged' && currentUser?.role === 'admin' ? 'border-2 border-red-200 bg-red-50' : ''}`}>
            {/* Admin Status Indicator */}
            {currentUser?.role === 'admin' && review.status !== 'active' && (
                 <div className="absolute top-2 right-2 px-2 py-0.5 bg-red-100 text-red-600 text-xs font-bold rounded uppercase">
                     {review.status}
                 </div>
            )}

            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <img 
                      src={review.userImage} 
                      alt={review.userName} 
                      className="w-10 h-10 rounded-full object-cover border border-gray-100" 
                    />
                    <div>
                        <div className="flex items-center gap-1">
                            <h5 className="font-bold text-dark text-sm">{review.userName}</h5>
                            {reviewUser.badges && reviewUser.badges.length > 0 && (
                                <div className="flex gap-1 ml-1">
                                    {reviewUser.badges.map(bid => {
                                        const badge = MOCK_BADGES.find(b => b.id === bid);
                                        if (!badge) return null;
                                        return (
                                            <div key={bid} title={badge.name} className="w-4 h-4 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center">
                                                <ShieldCheck size={10} />
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                        <span className="text-xs text-gray-400">{new Date(review.date).toLocaleDateString()}</span>
                    </div>
                </div>
                <div className="flex bg-yellow-50 px-2 py-1 rounded text-yellow-600 font-bold text-xs">
                    <Star size={12} className="fill-yellow-600 mr-1" /> {review.rating}.0
                </div>
            </div>

            <p className="text-graytext text-sm mb-4 leading-relaxed">{review.text}</p>

            {/* Review Photos (Phase 2) */}
            {review.photos && review.photos.length > 0 && (
                <div className="flex gap-2 mb-4 overflow-x-auto pb-2">
                    {review.photos.map((photo, i) => (
                        <img key={i} src={photo} alt="Review attachment" className="h-20 w-20 object-cover rounded-lg border border-gray-100" />
                    ))}
                </div>
            )}

            <div className="flex items-center justify-between border-t border-gray-100 pt-4">
                <div className="flex items-center gap-4">
                    {/* Helpful Vote */}
                    <button 
                        onClick={handleLike}
                        disabled={isReviewAuthor}
                        className={`flex items-center gap-1.5 text-xs font-bold transition-colors ${
                            liked ? 'text-primary' : 
                            isReviewAuthor ? 'text-gray-300 cursor-not-allowed' : 'text-gray-400 hover:text-dark'
                        }`}
                        title={isReviewAuthor ? "You cannot vote on your own review" : "Mark as helpful"}
                    >
                        <ThumbsUp size={14} className={liked ? "fill-primary" : ""} /> 
                        Helpful ({likeCount})
                    </button>

                    {/* Vendor Reply Trigger */}
                    {isOwner && !review.reply && (
                        <button className="flex items-center gap-1.5 text-xs font-bold text-gray-400 hover:text-primary transition-colors">
                            <MessageCircle size={14} /> Reply
                        </button>
                    )}
                </div>

                {/* Report Button */}
                {!isReported ? (
                    <button 
                        onClick={handleReport} 
                        className="text-gray-300 hover:text-red-500 transition-colors"
                        title="Report abuse"
                    >
                        <Flag size={14} />
                    </button>
                ) : (
                    <span className="text-xs text-red-500 font-medium">Reported</span>
                )}
            </div>

            {/* Vendor Reply Display (Phase 3) */}
            {review.reply && (
                <div className="mt-4 bg-gray-50 rounded-xl p-4 ml-4 border-l-2 border-primary">
                    <div className="flex items-center gap-2 mb-1">
                        <CornerDownRight size={14} className="text-gray-400" />
                        <span className="text-xs font-bold text-dark">Response from Owner</span>
                        <span className="text-[10px] text-gray-400">• {new Date(review.reply.date).toLocaleDateString()}</span>
                    </div>
                    <p className="text-xs text-gray-600">{review.reply.text}</p>
                </div>
            )}
        </div>
    );
};

import { AnalyticsEvent, DailyMetric } from '../types';
import { MOCK_BUSINESSES, MOCK_REVIEWS, MOCK_USERS_LIST } from '../constants';

const EVENTS_KEY = 'instaconnect_raw_events';
const METRICS_KEY = 'instaconnect_daily_metrics';

class AnalyticsService {
  private events: AnalyticsEvent[] = [];
  private metrics: DailyMetric[] = [];

  constructor() {
    this.loadData();
    this.seedDataIfEmpty();
  }

  private loadData() {
    const storedEvents = localStorage.getItem(EVENTS_KEY);
    const storedMetrics = localStorage.getItem(METRICS_KEY);

    if (storedEvents) this.events = JSON.parse(storedEvents);
    if (storedMetrics) this.metrics = JSON.parse(storedMetrics);
  }

  private saveData() {
    localStorage.setItem(EVENTS_KEY, JSON.stringify(this.events));
    localStorage.setItem(METRICS_KEY, JSON.stringify(this.metrics));
  }

  // --- Tracking Methods ---

  public trackEvent(
    type: AnalyticsEvent['type'],
    businessId: string,
    userId?: string
  ) {
    const event: AnalyticsEvent = {
      id: Math.random().toString(36).substr(2, 9),
      businessId,
      type,
      timestamp: Date.now(),
      userId
    };

    this.events.push(event);
    this.saveData();
    // Also update realtime metrics for today immediately for better UX
    this.updateTodayMetric(event);
  }

  // --- Aggregation Logic (The "Engine") ---

  private updateTodayMetric(event: AnalyticsEvent) {
    const today = new Date().toISOString().split('T')[0];
    let metric = this.metrics.find(m => m.date === today && m.businessId === event.businessId);

    if (!metric) {
      metric = {
        date: today,
        businessId: event.businessId,
        views: 0,
        clicks: 0,
        shares: 0
      };
      this.metrics.push(metric);
    }

    if (event.type === 'view') metric.views++;
    else if (event.type === 'share') metric.shares++;
    else metric.clicks++; // All other types are clicks

    this.saveData();
  }

  // Called by Cron Job to ensure all raw events are processed into daily buckets
  public aggregateEvents() {
    console.log('[Analytics Engine] Running aggregation job...');

    // In a real app, we might process raw events and archive them.
    // Here, we just ensure our metrics map is consistent with events.
    // For this mock implementation, updateTodayMetric handles real-time, 
    // but this method could be used to re-calculate history if needed.

    // Simulating "archiving" old events to keep storage light
    const oneWeekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
    const oldEventsCount = this.events.length;
    this.events = this.events.filter(e => e.timestamp > oneWeekAgo);

    if (this.events.length < oldEventsCount) {
        console.log(`[Analytics Engine] Archived ${oldEventsCount - this.events.length} old events.`);
        this.saveData();
    }
  }

  // --- Reporting Methods ---

  public getBusinessMetrics(businessId: string, days: number = 7) {
    const result = [];
    for (let i = days - 1; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];

      const metric = this.metrics.find(m => m.date === dateStr && m.businessId === businessId) || {
        date: dateStr,
        businessId,
        views: 0,
        clicks: 0,
        shares: 0
      };
      result.push(metric);
    }
    return result;
  }

  public getBusinessLifetimeStats(businessId: string) {
    return this.metrics
        .filter(m => m.businessId === businessId)
        .reduce((acc, curr) => ({
            views: acc.views + curr.views,
            clicks: acc.clicks + curr.clicks,
            shares: acc.shares + curr.shares
        }), { views: 0, clicks: 0, shares: 0 });
  }

  public getGlobalMetrics(days: number = 7) {
    const result = [];
    for (let i = days - 1; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];

      // Aggregate all businesses for this day
      const dayMetrics = this.metrics.filter(m => m.date === dateStr);

      const totalViews = dayMetrics.reduce((sum, m) => sum + m.views, 0);
      const totalClicks = dayMetrics.reduce((sum, m) => sum + m.clicks, 0);

      result.push({
          date: dateStr,
          views: totalViews,
          clicks: totalClicks
      });
    }
    return result;
  }

  // --- Admin API Endpoints (Simulated) ---

  /**
   * Endpoint: /admin/analytics/overview
   * Description: Fetches high-level KPIs for the admin dashboard.
   * Security: AdminGuard (simulated via role check)
   */
  public getAdminOverview(userRole: string) {
    if (userRole !== 'admin') {
      throw new Error('Forbidden: Access denied. Admin role required.');
    }

    // Aggregating data from "DB"
    const totalViews = this.metrics.reduce((acc, m) => acc + m.views, 0);

    return {
      totalUsers: MOCK_USERS_LIST.length,
      activeBusinesses: MOCK_BUSINESSES.filter(b => b.isOpen).length,
      totalReviews: MOCK_REVIEWS.length,
      pendingReports: MOCK_REVIEWS.filter(r => r.status === 'flagged').length,
      revenue: 1250000,
      totalViews: totalViews
    };
  }

  /**
   * Endpoint: /admin/analytics/growth
   * Description: Fetches historical growth data.
   * Security: AdminGuard (simulated via role check)
   */
  public getAdminGrowth(userRole: string, days: number = 30) {
    if (userRole !== 'admin') {
      throw new Error('Forbidden: Access denied. Admin role required.');
    }

    return this.getGlobalMetrics(days);
  }

  // --- Mock Data Seeding ---
  private seedDataIfEmpty() {
    if (this.metrics.length > 0) return;
    console.log('[Analytics Engine] Seeding mock historical data...');

    const today = new Date();

    MOCK_BUSINESSES.forEach(biz => {
        // Generate 30 days of data
        for (let i = 0; i < 30; i++) {
            const date = new Date(today);
            date.setDate(date.getDate() - i);
            const dateStr = date.toISOString().split('T')[0];

            // Random realistic data
            // Trend: traffic is slightly higher on weekends (Fri=5, Sat=6)
            const isWeekend = date.getDay() === 5 || date.getDay() === 6;
            const baseViews = Math.floor(Math.random() * 20) + 10;
            const multiplier = isWeekend ? 1.5 : 1;

            this.metrics.push({
                date: dateStr,
                businessId: biz.id,
                views: Math.floor(baseViews * multiplier),
                clicks: Math.floor(baseViews * multiplier * 0.2), // 20% CTR
                shares: Math.floor(baseViews * 0.05)
            });
        }
    });
    this.saveData();
  }
}

