import { AnalyticsEvent, DailyMetric } from '../types';
import { MOCK_BUSINESSES, MOCK_REVIEWS, MOCK_USERS_LIST } from '../constants';

const EVENTS_KEY = 'instaconnect_raw_events';
const METRICS_KEY = 'instaconnect_daily_metrics';

class AnalyticsService {
  private events: AnalyticsEvent[] = [];
  private metrics: DailyMetric[] = [];

  constructor() {
    this.loadData();
    this.seedDataIfEmpty();
  }

  private loadData() {
    const storedEvents = localStorage.getItem(EVENTS_KEY);
    const storedMetrics = localStorage.getItem(METRICS_KEY);

    if (storedEvents) this.events = JSON.parse(storedEvents);
    if (storedMetrics) this.metrics = JSON.parse(storedMetrics);
  }

  private saveData() {
    localStorage.setItem(EVENTS_KEY, JSON.stringify(this.events));
    localStorage.setItem(METRICS_KEY, JSON.stringify(this.metrics));
  }

  // --- Tracking Methods ---

  public trackEvent(
    type: AnalyticsEvent['type'],
    businessId: string,
    userId?: string
  ) {
    const event: AnalyticsEvent = {
      id: Math.random().toString(36).substr(2, 9),
      businessId,
      type,
      timestamp: Date.now(),
      userId
    };

    this.events.push(event);
    this.saveData();
    // Also update realtime metrics for today immediately for better UX
    this.updateTodayMetric(event);
  }

  // --- Aggregation Logic (The "Engine") ---

  private updateTodayMetric(event: AnalyticsEvent) {
    const today = new Date().toISOString().split('T')[0];
    let metric = this.metrics.find(m => m.date === today && m.businessId === event.businessId);

    if (!metric) {
      metric = {
        date: today,
        businessId: event.businessId,
        views: 0,
        clicks: 0,
        shares: 0
      };
      this.metrics.push(metric);
    }

    if (event.type === 'view') metric.views++;
    else if (event.type === 'share') metric.shares++;
    else metric.clicks++; // All other types are clicks

    this.saveData();
  }

  // Called by Cron Job to ensure all raw events are processed into daily buckets
  public aggregateEvents() {
    console.log('[Analytics Engine] Running aggregation job...');

    // In a real app, we might process raw events and archive them.
    // Here, we just ensure our metrics map is consistent with events.
    // For this mock implementation, updateTodayMetric handles real-time, 
    // but this method could be used to re-calculate history if needed.

    // Simulating "archiving" old events to keep storage light
    const oneWeekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
    const oldEventsCount = this.events.length;
    this.events = this.events.filter(e => e.timestamp > oneWeekAgo);

    if (this.events.length < oldEventsCount) {
        console.log(`[Analytics Engine] Archived ${oldEventsCount - this.events.length} old events.`);
        this.saveData();
    }
  }

  // --- Reporting Methods ---

  public getBusinessMetrics(businessId: string, days: number = 7) {
    const result = [];
    for (let i = days - 1; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];

      const metric = this.metrics.find(m => m.date === dateStr && m.businessId === businessId) || {
        date: dateStr,
        businessId,
        views: 0,
        clicks: 0,
        shares: 0
      };
      result.push(metric);
    }
    return result;
  }

  public getBusinessLifetimeStats(businessId: string) {
    return this.metrics
        .filter(m => m.businessId === businessId)
        .reduce((acc, curr) => ({
            views: acc.views + curr.views,
            clicks: acc.clicks + curr.clicks,
            shares: acc.shares + curr.shares
        }), { views: 0, clicks: 0, shares: 0 });
  }

  public getGlobalMetrics(days: number = 7) {
    const result = [];
    for (let i = days - 1; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];

      // Aggregate all businesses for this day
      const dayMetrics = this.metrics.filter(m => m.date === dateStr);

      const totalViews = dayMetrics.reduce((sum, m) => sum + m.views, 0);
      const totalClicks = dayMetrics.reduce((sum, m) => sum + m.clicks, 0);

      result.push({
          date: dateStr,
          views: totalViews,
          clicks: totalClicks
      });
    }
    return result;
  }

  // --- Admin API Endpoints (Simulated) ---

  /**
   * Endpoint: /admin/analytics/overview
   * Description: Fetches high-level KPIs for the admin dashboard.
   * Security: AdminGuard (simulated via role check)
   */
  public getAdminOverview(userRole: string) {
    if (userRole !== 'admin') {
      throw new Error('Forbidden: Access denied. Admin role required.');
    }

    // Aggregating data from "DB"
    const totalViews = this.metrics.reduce((acc, m) => acc + m.views, 0);

    return {
      totalUsers: MOCK_USERS_LIST.length,
      activeBusinesses: MOCK_BUSINESSES.filter(b => b.isOpen).length,
      totalReviews: MOCK_REVIEWS.length,
      pendingReports: MOCK_REVIEWS.filter(r => r.status === 'flagged').length,
      revenue: 1250000,
      totalViews: totalViews
    };
  }

  /**
   * Endpoint: /admin/analytics/trends
   * Description: Fetches 30-day trend data for users, businesses, and reviews.
   */
  public getDashboardTrends(days: number = 30) {
    const data = [];
    const today = new Date();

    // Starting baseline for cumulative metric (businesses)
    let currentBusinesses = 45;

    for (let i = days - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const dateStr = d.toISOString().split('T')[0];

        // Generate realistic mock trends
        const newUsers = Math.floor(Math.random() * 15) + 5; // 5-20 daily new users
        const newReviews = Math.floor(Math.random() * 25) + 10; // 10-35 daily reviews

        // Occasionally add a new business to the cumulative total
        if (Math.random() > 0.7) currentBusinesses++; 

        data.push({
            date: dateStr,
            newUsers,
            activeBusinesses: currentBusinesses,
            newReviews
        });
    }
    return data;
  }

  /**
   * Endpoint: /admin/analytics/growth
   * Description: Fetches historical growth data (views/clicks).
   * Security: AdminGuard (simulated via role check)
   */
  public getAdminGrowth(userRole: string, days: number = 30) {
    if (userRole !== 'admin') {
      throw new Error('Forbidden: Access denied. Admin role required.');
    }

    return this.getGlobalMetrics(days);
  }

  // --- Mock Data Seeding ---
  private seedDataIfEmpty() {
    if (this.metrics.length > 0) return;
    console.log('[Analytics Engine] Seeding mock historical data...');

    const today = new Date();

    MOCK_BUSINESSES.forEach(biz => {
        // Generate 30 days of data
        for (let i = 0; i < 30; i++) {
            const date = new Date(today);
            date.setDate(date.getDate() - i);
            const dateStr = date.toISOString().split('T')[0];

            // Random realistic data
            // Trend: traffic is slightly higher on weekends (Fri=5, Sat=6)
            const isWeekend = date.getDay() === 5 || date.getDay() === 6;
            const baseViews = Math.floor(Math.random() * 20) + 10;
            const multiplier = isWeekend ? 1.5 : 1;

            this.metrics.push({
                date: dateStr,
                businessId: biz.id,
                views: Math.floor(baseViews * multiplier),
                clicks: Math.floor(baseViews * multiplier * 0.2), // 20% CTR
                shares: Math.floor(baseViews * 0.05)
            });
        }
    });
    this.saveData();
  }
}

