import { Notification, User } from '../types';
import { MOCK_USERS_LIST } from '../constants';

const NOTIFICATIONS_KEY = 'insta_notifications';

class NotificationService {

  // Send a review notification to a business owner
  public notifyReview(ownerId: string, businessName: string, reviewerName: string) {
    // 1. Fetch user preferences (Simulated)
    // Try to get from local storage if it's the currently logged in user (mock scenario), 
    // otherwise fallback to static mock data
    const storedUser = localStorage.getItem('insta_user');
    let user: User | undefined;

    if (storedUser) {
        const parsed = JSON.parse(storedUser);
        if (parsed.id === ownerId) {
            user = parsed;
        }
    }

    if (!user) {
        user = MOCK_USERS_LIST.find(u => u.id === ownerId);
    }

    if (!user) {
        console.warn(`[Notification] User ${ownerId} not found.`);
        return;
    }

    // 2. Check Preferences
    const { email, inApp } = user.notificationPreferences || { email: true, inApp: true };

    const notification: Notification = {
        id: Math.random().toString(36).substr(2, 9),
        userId: ownerId,
        type: 'review',
        title: 'New Review Received',
        message: `${reviewerName} just left a review for ${businessName}.`,
        date: new Date().toISOString(),
        isRead: false,
        link: '/dashboard' // In real app, deep link to specific review
    };

    // 3. Dispatch Notifications
    if (email) {
        this.sendEmail(user.email, notification);
    }

    if (inApp) {
        this.storeInAppNotification(notification);
    }
  }

  // Simulate Email Sending
  private sendEmail(email: string, notification: Notification) {
      console.log(`%c[Email Service] Sending to ${email}:`, 'color: cyan; font-weight: bold;');
      console.log(`Subject: ${notification.title}`);
      console.log(`Body: ${notification.message}`);
  }

  // Store in Local Storage for In-App display
  private storeInAppNotification(notification: Notification) {
      const existing = this.getAllNotifications();
      const updated = [notification, ...existing];
      localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(updated));
      console.log(`[Notification] In-app notification stored for user ${notification.userId}`);
  }

  public getNotifications(userId: string): Notification[] {
      const all = this.getAllNotifications();
      return all.filter(n => n.userId === userId);
  }

  public markAsRead(notificationId: string) {
      const all = this.getAllNotifications();
      const updated = all.map(n => n.id === notificationId ? { ...n, isRead: true } : n);
      localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(updated));
  }

  public markAllAsRead(userId: string) {
      const all = this.getAllNotifications();
      const updated = all.map(n => n.userId === userId ? { ...n, isRead: true } : n);
      localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(updated));
  }

  private getAllNotifications(): Notification[] {
      const stored = localStorage.getItem(NOTIFICATIONS_KEY);
      return stored ? JSON.parse(stored) : [];
  }
}

export const notificationService = new NotificationService();

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User } from '../types';
import { MOCK_USER } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (email: string, pass: string) => Promise<void>;
  register: (name: string, email: string, pass: string, role: 'consumer' | 'vendor') => Promise<void>;
  logout: () => void;
  updateCredits: (amount: number) => void;
  updateUser: (data: Partial<User>) => void;
  isLoading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Check local storage for persistent auth (mocking)
    const storedUser = localStorage.getItem('insta_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setIsLoading(false);
  }, []);

  const login = async (email: string, pass: string) => {
    // Mock login delay
    await new Promise(resolve => setTimeout(resolve, 800));

    // Determine role based on email for demo purposes
    let role: 'consumer' | 'vendor' | 'admin' = 'consumer';
    const lowerEmail = email.toLowerCase();

    if (lowerEmail.includes('admin')) {
        role = 'admin';
    } else if (lowerEmail.includes('vendor')) {
        role = 'vendor';
    }

    // Create user with appropriate ID mapping
    // ID '1' owns the mock business, so we give it to vendors for testing dashboard
    const newUser: User = {
        ...MOCK_USER,
        id: role === 'vendor' ? '1' : (role === 'admin' ? 'admin-1' : Math.random().toString(36).substr(2, 9)),
        email: email,
        name: email.split('@')[0].charAt(0).toUpperCase() + email.split('@')[0].slice(1), // Use email handle as name
        role: role,
        image: `https://ui-avatars.com/api/?name=${encodeURIComponent(email.split('@')[0])}&background=random`
    };

    // Keep original mock data if logging in as the default hardcoded user
    if (email === MOCK_USER.email) {
         newUser.id = MOCK_USER.id;
         newUser.name = MOCK_USER.name;
         newUser.image = MOCK_USER.image;
         newUser.role = MOCK_USER.role;
         newUser.notificationPreferences = MOCK_USER.notificationPreferences;
    }

    setUser(newUser);
    localStorage.setItem('insta_user', JSON.stringify(newUser));
  };

  const register = async (name: string, email: string, pass: string, role: 'consumer' | 'vendor') => {
    // Mock register delay
    await new Promise(resolve => setTimeout(resolve, 800));
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      email,
      image: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=random`,
      role: role,
      credits: 0,
      badges: [],
      reputationPoints: 0,
      referralCode: Math.random().toString(36).substr(2, 8).toUpperCase(),
      referralCount: 0,
      notificationPreferences: { email: true, inApp: true }
    };
    setUser(newUser);
    localStorage.setItem('insta_user', JSON.stringify(newUser));
  };

  const updateCredits = (amount: number) => {
    if (user) {
      const updatedUser = { ...user, credits: user.credits + amount };
      setUser(updatedUser);
      localStorage.setItem('insta_user', JSON.stringify(updatedUser));
    }
  };

  const updateUser = (data: Partial<User>) => {
      if (user) {
          const updatedUser = { ...user, ...data };
          setUser(updatedUser);
          localStorage.setItem('insta_user', JSON.stringify(updatedUser));
      }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('insta_user');
  };

  return (
    <AuthContext.Provider value={{ user, login, register, logout, updateCredits, updateUser, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

