                                      >
                                          <Check size={16} /> Keep
                                      </button>
                                      <button 
                                          onClick={() => handleModeration(review.id, 'delete')}
                                          className="flex items-center justify-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-xl font-bold text-sm transition-colors"
                                      >
                                          <Ban size={16} /> Remove
                                      </button>
                                  </div>
                              </div>
                          ))}
                      </div>
                  )}
              </div>
          )}

          {/* --- SETTINGS TAB --- */}
          {activeTab === 'settings' && (
              <div className="max-w-2xl animate-fade-in">
                  <h2 className="text-2xl font-bold text-white mb-6">System Configuration</h2>
                  <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700 space-y-6">
                      <div>
                          <label className="block text-sm font-bold text-gray-400 mb-2">Platform Name</label>
                          <input type="text" value="InstaConnect NG" className="w-full bg-gray-900 border border-gray-700 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" readOnly />
                      </div>
                      <div>
                          <label className="block text-sm font-bold text-gray-400 mb-2">Admin Email</label>
                          <input type="email" value={user.email} className="w-full bg-gray-900 border border-gray-700 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" readOnly />
                      </div>
                      <div className="pt-4 border-t border-gray-700">
                          <h3 className="text-white font-bold mb-4">API Keys</h3>
                          <div className="space-y-4">
                              <div className="relative">
                                  <input type="password" value="sk-ant-xxx-xxx" className="w-full bg-gray-900 border border-gray-700 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" readOnly />
                                  <button className="absolute right-4 top-3.5 text-gray-500 hover:text-white"><EyeOff size={18} /></button>
                              </div>
                          </div>
                      </div>
                      <div className="flex justify-end pt-4">
                          <button className="bg-primary text-white font-bold px-6 py-3 rounded-xl hover:bg-red-600 transition-colors">Save Changes</button>
                      </div>
                  </div>
              </div>
          )}

        </main>
      </div>
    </div>
  );
};

