      </div>
      {trend && (
        <div className={`flex items-center gap-1 text-xs font-bold px-2 py-1 rounded-full ${
          trend > 0 ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'
        }`}>
          {trend > 0 ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} />}
          {Math.abs(trend)}%
        </div>
      )}
    </div>
  </div>
);

const AdminDashboard: React.FC = () => {
  const { user, isLoading, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'overview' | 'businesses' | 'users' | 'finance' | 'moderation' | 'settings'>('overview');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Data State
  const [trendData, setTrendData] = useState<any[]>([]);
  const [revenueData, setRevenueData] = useState<any[]>([]);
  const [categoryData, setCategoryData] = useState<any[]>([]);
  const [retentionData, setRetentionData] = useState<any>({ rate: 0, trend: 0 });
  const [usersList, setUsersList] = useState<User[]>(MOCK_USERS_LIST);

  // Moderation State
  const [flaggedReviews, setFlaggedReviews] = useState<Review[]>([]);

  // User Search
  const [userSearch, setUserSearch] = useState('');

  // Colors
  const COLORS = ['#EE1C47', '#FF823A', '#10B981', '#3B82F6', '#8B5CF6', '#F59E0B'];

  useEffect(() => {
    if (!isLoading) {
      if (!user || user.role !== 'admin') {
        navigate('/login');
        return;
      }

      // Fetch Analytics
      setTrendData(analyticsService.getDashboardTrends(30));
      setRevenueData(analyticsService.getRevenueAnalytics());
      setCategoryData(analyticsService.getCategoryDistribution());
      setRetentionData(analyticsService.getRetentionStats());

      // Fetch Flagged Content
      setFlaggedReviews(MOCK_REVIEWS.filter(r => r.status === 'flagged'));

      // Check localStorage for banned users and update initial list
      const bannedEmails = JSON.parse(localStorage.getItem('banned_users') || '[]');
      if (bannedEmails.length > 0) {
          const updatedList = MOCK_USERS_LIST.map(u => ({
              ...u,
              status: bannedEmails.includes(u.email) ? 'banned' : 'active'
          }));
          setUsersList(updatedList as User[]);
      }
    }
  }, [user, isLoading, navigate]);

  const handleModeration = (id: string, action: 'approve' | 'delete') => {
      if (action === 'approve') {
          setFlaggedReviews(prev => prev.filter(r => r.id !== id));
      } else {
          setFlaggedReviews(prev => prev.filter(r => r.id !== id));
      }
  };

  const handleBanUser = (targetUser: User) => {
      const isBanned = targetUser.status === 'banned';
      const action = isBanned ? 'activate' : 'suspend';

      if(window.confirm(`Are you sure you want to ${action} this user account?`)) {
          // Update local state
          const updatedList = usersList.map(u => 
              u.id === targetUser.id ? { ...u, status: isBanned ? 'active' : 'banned' } : u
          );
          setUsersList(updatedList as User[]);

          // Update localStorage for persistence across login
          const bannedEmails = JSON.parse(localStorage.getItem('banned_users') || '[]');
          if (!isBanned) {
              // Banning
              if (!bannedEmails.includes(targetUser.email)) {
                  bannedEmails.push(targetUser.email);
              }
          } else {
              // Unbanning
              const index = bannedEmails.indexOf(targetUser.email);
              if (index > -1) {
                  bannedEmails.splice(index, 1);
              }
          }
          localStorage.setItem('banned_users', JSON.stringify(bannedEmails));

          alert(`User ${targetUser.name} has been ${isBanned ? 'activated' : 'suspended'}.`);
      }
  };

  const handleUserRoleChange = (userId: string, newRole: 'consumer' | 'vendor' | 'admin') => {
      setUsersList(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
