          // Update local state
          const updatedList = usersList.map(u => 
              u.id === targetUser.id ? { ...u, status: isBanned ? 'active' : 'banned' } : u
          );
          setUsersList(updatedList as User[]);

          // Update localStorage for persistence across login
          const bannedEmails = JSON.parse(localStorage.getItem('banned_users') || '[]');
          if (!isBanned) {
              // Banning
              if (!bannedEmails.includes(targetUser.email)) {
                  bannedEmails.push(targetUser.email);
              }
          } else {
              // Unbanning
              const index = bannedEmails.indexOf(targetUser.email);
              if (index > -1) {
