const AdminDashboard: React.FC = () => {
  const { user, isLoading, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'overview' | 'businesses' | 'users' | 'finance' | 'moderation' | 'settings'>('overview');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Date Range State
  const [dateRange, setDateRange] = useState({
    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  // Data State
  const [trendData, setTrendData] = useState<any[]>([]);
  const [revenueData, setRevenueData] = useState<any[]>([]);
  const [categoryData, setCategoryData] = useState<any[]>([]);
  const [retentionData, setRetentionData] = useState<any>({ rate: 0, trend: 0 });
  const [usersList, setUsersList] = useState<User[]>(MOCK_USERS_LIST);
  const [adminOverview, setAdminOverview] = useState<any>(null);
  const [userGrowthData, setUserGrowthData] = useState<any>(null);
  const [categoryChartData, setCategoryChartData] = useState<any>(null);
  const [pendingBusinesses, setPendingBusinesses] = useState<Business[]>([]);

  // Moderation State
  const [flaggedReviews, setFlaggedReviews] = useState<Review[]>([]);

  // User Search
  const [userSearch, setUserSearch] = useState('');

  // Colors
  const COLORS = ['#EE1C47', '#FF823A', '#10B981', '#3B82F6', '#8B5CF6', '#F59E0B'];

  // Mock Traffic Sources Data
  const trafficSourceData = [
    { name: 'Instagram', value: 45, color: '#E1306C' },
    { name: 'Direct', value: 30, color: '#3B82F6' },
    { name: 'Google', value: 15, color: '#10B981' },
    { name: 'Referral', value: 10, color: '#F59E0B' },
  ];

  useEffect(() => {
    if (!isLoading) {
      if (!user || user.role !== 'admin') {
        navigate('/login');
        return;
      }

      // Calculate days difference for dynamic data fetching based on selected range
      const start = new Date(dateRange.start);
      const end = new Date(dateRange.end);
      const diffTime = Math.abs(end.getTime() - start.getTime());
      const daysDiff = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) || 1; 

      // Fetch Analytics with date range params
      setTrendData(analyticsService.getDashboardTrends(daysDiff));
      setRevenueData(analyticsService.getRevenueAnalytics());
      setCategoryData(analyticsService.getCategoryDistribution());
      setRetentionData(analyticsService.getRetentionStats());
      setAdminOverview(analyticsService.getAdminOverview('admin'));

      // Fetch User Growth Data for Chart.js
      // Passing daysDiff as part of the period string like '30d' to update the chart dynamically
      const growthSeries = analyticsService.getNewUsersTimeSeries('admin', `${daysDiff}d`);
      setUserGrowthData({
          labels: growthSeries.map(d => new Date(d.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })),
          datasets: [{
              label: 'New Users',
              data: growthSeries.map(d => d.count),
              borderColor: '#10B981', // Emerald 500
              backgroundColor: 'rgba(16, 185, 129, 0.1)',
              borderWidth: 2,
              fill: true,
              tension: 0.4,
              pointRadius: 4,
              pointHoverRadius: 6
          }]
      });

      // Fetch Category Distribution for Chart.js
      const categoryStats = analyticsService.getBusinessCategoryDistribution('admin');
      setCategoryChartData({
          labels: categoryStats.map(d => d.name),
          datasets: [{
              data: categoryStats.map(d => d.value),
              backgroundColor: COLORS,
              hoverOffset: 4
          }]
      });

      // Fetch Flagged Content
      setFlaggedReviews(MOCK_REVIEWS.filter(r => r.status === 'flagged'));

      // Fetch Pending Businesses
      setPendingBusinesses(MOCK_BUSINESSES.filter(b => b.verificationStatus === 'pending'));

      // Check localStorage for banned users and update initial list
      const bannedEmails = JSON.parse(localStorage.getItem('banned_users') || '[]');
      if (bannedEmails.length > 0) {
          const updatedList = MOCK_USERS_LIST.map(u => ({
              ...u,
              status: bannedEmails.includes(u.email) ? 'banned' : 'active'
          }));
          setUsersList(updatedList as User[]);
      }
    }
  }, [user, isLoading, navigate, dateRange]);

  const handleModeration = (id: string, action: 'approve' | 'delete') => {
      if (action === 'approve') {
          setFlaggedReviews(prev => prev.filter(r => r.id !== id));
      } else {
          setFlaggedReviews(prev => prev.filter(r => r.id !== id));
      }
  };

  const handleBanUser = (targetUser: User) => {
      const isBanned = targetUser.status === 'banned';
      const action = isBanned ? 'activate' : 'suspend';

      if(window.confirm(`Are you sure you want to ${action} this user account?`)) {
          // Update local state
          const updatedList = usersList.map(u => 
              u.id === targetUser.id ? { ...u, status: isBanned ? 'active' : 'banned' } : u
          );
          setUsersList(updatedList as User[]);

          // Update localStorage for persistence across login
          const bannedEmails = JSON.parse(localStorage.getItem('banned_users') || '[]');
          if (!isBanned) {
              // Banning
              if (!bannedEmails.includes(targetUser.email)) {
                  bannedEmails.push(targetUser.email);
              }
          } else {
              // Unbanning
              const index = bannedEmails.indexOf(targetUser.email);
              if (index > -1) {
                  bannedEmails.splice(index, 1);
              }
          }
          localStorage.setItem('banned_users', JSON.stringify(bannedEmails));

          alert(`User ${targetUser.name} has been ${isBanned ? 'activated' : 'suspended'}.`);
      }
  };

  const handleUserRoleChange = (userId: string, newRole: 'consumer' | 'vendor' | 'admin') => {
      setUsersList(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
  };

  const handleApproveBusiness = (id: string) => {
      if (window.confirm('Are you sure you want to approve this business listing?')) {
          setPendingBusinesses(prev => prev.filter(b => b.id !== id));
          // In a real app, you would make an API call here to update the status
          // analyticsService.updateBusinessStatus(id, 'verified'); 
          alert('Business approved successfully.');
      }
  };

  const handleRejectBusiness = (id: string) => {
      if (window.confirm('Are you sure you want to reject this submission?')) {
          setPendingBusinesses(prev => prev.filter(b => b.id !== id));
          alert('Business submission rejected.');
      }
  };

  const filteredUsers = usersList.filter(u => 
    u.name.toLowerCase().includes(userSearch.toLowerCase()) || 
    u.email.toLowerCase().includes(userSearch.toLowerCase())
  );

  // Define Columns for Pending Businesses Table
  const pendingBusinessColumns: Column<Business>[] = [
      {
          header: 'Business Name',
          render: (row) => (
              <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-gray-700 overflow-hidden">
                      <img src={row.image} alt="" className="w-full h-full object-cover" />
                  </div>
                  <span className="font-bold text-white">{row.name}</span>
              </div>
          )
      },
      {
          header: 'Category',
          accessorKey: 'category',
          render: (row) => <span className="bg-gray-700 px-2 py-1 rounded text-xs text-gray-300">{row.category}</span>
      },
      {
          header: 'Submitted Date',
          render: (row) => row.createdAt ? new Date(row.createdAt).toLocaleDateString() : 'N/A'
      },
      {
          header: 'Status',
          render: () => (
              <span className="flex items-center gap-1 text-yellow-400 text-xs font-bold bg-yellow-400/10 px-2 py-1 rounded-full w-fit">
                  <Clock size={12}/> Pending Review
              </span>
          )
      },
      {
          header: 'Actions',
          className: 'text-right',
          render: (row) => (
              <div className="flex justify-end gap-2">
                  <button 
                      onClick={() => handleApproveBusiness(row.id)}
                      className="p-1.5 bg-green-500/10 hover:bg-green-500/20 text-green-500 rounded-lg transition-colors" 
                      title="Approve"
                  >
                      <Check size={16} />
                  </button>
                  <button 
                      onClick={() => handleRejectBusiness(row.id)}
                      className="p-1.5 bg-red-500/10 hover:bg-red-500/20 text-red-500 rounded-lg transition-colors" 
                      title="Reject"
                  >
                      <X size={16} />
                  </button>
              </div>
          )
      }
  ];

  // Business Metrics Calculation
  const businessMetrics = {
    total: MOCK_BUSINESSES.length,
    new30d: MOCK_BUSINESSES.filter(b => {
        const created = new Date(b.createdAt || '2023-01-01');
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        return created > thirtyDaysAgo;
    }).length,
    active90d: MOCK_BUSINESSES.filter(b => {
        const lastActive = new Date(b.lastActiveAt || '2023-01-01');
        const ninetyDaysAgo = new Date();
        ninetyDaysAgo.setDate(ninetyDaysAgo.getDate() - 90);
        return lastActive > ninetyDaysAgo;
    }).length,
    pending: MOCK_BUSINESSES.filter(b => b.verificationStatus === 'pending').length,
    promoted: MOCK_BUSINESSES.filter(b => b.isPromoted).length
  };

  // User & Consumer Metrics
  const userMetrics = {
    totalConsumers: usersList.filter(u => u.role === 'consumer').length,
    activeNow: trendData.length > 0 ? trendData[trendData.length - 1].visitorOnline : 0,
    mau: usersList.filter(u => {
        if (!u.lastActiveAt) return false;
        const lastActive = new Date(u.lastActiveAt);
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        return lastActive > thirtyDaysAgo;
    }).length,
    retentionRate: retentionData.rate,
    totalReviews: MOCK_REVIEWS.length,
    newReviews: MOCK_REVIEWS.filter(r => {
        const created = new Date(r.date);
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        return created > thirtyDaysAgo;
    }).length
  };

  // Finance Metrics Calculation
  const financeMetrics = {
    totalRevenue: MOCK_TRANSACTIONS
        .filter(t => t.type === 'credit_purchase' && t.status === 'success')
        .reduce((sum, t) => sum + (t.amountNGN || 0), 0),

    // MRR estimated from last 30 days revenue
    mrr: MOCK_TRANSACTIONS
        .filter(t => t.type === 'credit_purchase' && t.status === 'success')
        .filter(t => {
            const date = new Date(t.date);
            const now = new Date();
            const diffTime = Math.abs(now.getTime() - date.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            return diffDays <= 30;
        })
        .reduce((sum, t) => sum + (t.amountNGN || 0), 0),

    creditsPurchased: MOCK_TRANSACTIONS
        .filter(t => t.type === 'credit_purchase' && t.status === 'success')
        .reduce((sum, t) => sum + t.amount, 0),

    creditsSpent: MOCK_TRANSACTIONS
        .filter(t => t.type === 'promotion_spend' && t.status === 'success')
        .reduce((sum, t) => sum + Math.abs(t.amount), 0),

    payingVendors: new Set(
        MOCK_TRANSACTIONS
            .filter(t => t.type === 'credit_purchase' && t.status === 'success')
            .map(t => t.businessId)
    ).size
  };

  const conversionRate = MOCK_BUSINESSES.length > 0 ? (financeMetrics.payingVendors / MOCK_BUSINESSES.length) * 100 : 0;

  // Prepare chart data for finance (Credit flow)
  const creditFlowData = [
      { name: 'Purchased', value: financeMetrics.creditsPurchased },
      { name: 'Spent', value: financeMetrics.creditsSpent }
  ];

  // Top Viewed Businesses
  const topViewedBusinesses = [...MOCK_BUSINESSES]
    .sort((a, b) => b.viewCount - a.viewCount)
    .slice(0, 10);

  if (isLoading || !user) return <div className="bg-gray-900 min-h-screen flex items-center justify-center text-white">Loading...</div>;

  return (
    <div className="bg-gray-900 min-h-screen text-white font-sans flex overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-gray-900 border-r border-gray-800 transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-4">
          <div className="flex items-center gap-3 px-2 mb-10 mt-2">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-primary to-secondary flex items-center justify-center text-white font-bold">I</div>
            <span className="text-xl font-bold tracking-tight">InstaAdmin</span>
          </div>

          <div className="space-y-1 flex-1">
            <div className="px-2 mb-2 text-xs font-bold text-gray-500 uppercase tracking-wider">Menu</div>
            <SidebarItem icon={LayoutDashboard} label="Overview" active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} />
            <SidebarItem icon={ShoppingBag} label="Businesses" active={activeTab === 'businesses'} onClick={() => setActiveTab('businesses')} />
            <SidebarItem icon={Users} label="Users" active={activeTab === 'users'} onClick={() => setActiveTab('users')} />
            <SidebarItem icon={CreditCard} label="Finance" active={activeTab === 'finance'} onClick={() => setActiveTab('finance')} />
            <SidebarItem 
                icon={MessageSquare} 
                label="Moderation" 
                active={activeTab === 'moderation'} 
                onClick={() => setActiveTab('moderation')} 
                count={flaggedReviews.length > 0 ? flaggedReviews.length : undefined}
            />
            <div className="px-2 mb-2 mt-6 text-xs font-bold text-gray-500 uppercase tracking-wider">System</div>
            <SidebarItem icon={Settings} label="Settings" active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} />
          </div>

          <div className="mt-auto pt-4 border-t border-gray-800">
            <button onClick={logout} className="w-full flex items-center gap-3 px-4 py-3 text-red-400 hover:bg-gray-800 rounded-xl transition-colors">
              <LogOut size={20} />
              <span className="font-medium text-sm">Log Out</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">

        {/* Topbar */}
        <header className="h-20 bg-gray-900 border-b border-gray-800 flex items-center justify-between px-6 lg:px-8">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden text-gray-400 hover:text-white">
              <Menu size={24} />
            </button>
            <h2 className="text-xl font-bold capitalize">{activeTab}</h2>
          </div>

          <div className="flex items-center gap-6">
            <div className="relative hidden md:block">
              <Search className="absolute left-3 top-2.5 text-gray-500" size={18} />
              <input 
                type="text" 
                placeholder="Search..." 
                className="bg-gray-800 border border-gray-700 text-sm text-white rounded-full pl-10 pr-4 py-2 w-64 focus:outline-none focus:border-primary transition-colors"
              />
            </div>
            <button className="relative text-gray-400 hover:text-white">
              <Bell size={20} />
              {flaggedReviews.length > 0 && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-primary rounded-full"></span>}
            </button>
            <div className="flex items-center gap-3">
                <img src={user.image} alt="" className="w-9 h-9 rounded-full border border-gray-700" />
                <div className="hidden md:block text-right">
                    <div className="text-sm font-bold">{user.name}</div>
                    <div className="text-xs text-gray-500">Admin</div>
                </div>
            </div>
          </div>
        </header>

        {/* Dashboard Content Area */}
        <main className="flex-1 overflow-y-auto bg-gray-900 p-6 lg:p-8">

            {/* ... (Previous Overview Code) ... */}
            {activeTab === 'overview' && (
                <div className="space-y-6">
                    {/* Date Range Picker Section */}
                    <div className="flex flex-col md:flex-row justify-between items-end mb-2 gap-4">
                        <div>
                            <h3 className="text-lg font-bold text-white">Dashboard Overview</h3>
                            <p className="text-gray-400 text-sm">Real-time platform insights</p>
                        </div>
                        <div className="flex items-center gap-2 bg-gray-800 p-1.5 rounded-xl border border-gray-700 shadow-sm">
                            <div className="relative">
                                <Calendar size={14} className="absolute left-2.5 top-2.5 text-gray-400 pointer-events-none" />
                                <input 
                                    type="date" 
                                    value={dateRange.start}
                                    onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                                    className="bg-transparent border-none text-white text-xs font-medium pl-8 pr-2 py-1.5 focus:ring-0 cursor-pointer outline-none bg-gray-800 rounded-lg hover:bg-gray-700 transition-colors"
                                />
                            </div>
                            <span className="text-gray-500 text-xs font-medium">to</span>
                            <div className="relative">
                                <input 
                                    type="date" 
                                    value={dateRange.end}
                                    onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                                    className="bg-transparent border-none text-white text-xs font-medium pl-2 pr-2 py-1.5 focus:ring-0 cursor-pointer outline-none bg-gray-800 rounded-lg hover:bg-gray-700 transition-colors"
                                />
                            </div>
                        </div>
                    </div>

                    {/* KPI Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        <KpiCard 
                            title="Total Businesses" 
                            value={adminOverview?.totalBusinesses || 0} 
                            icon={ShoppingBag}
                            trend={adminOverview?.trends?.business}
                        />
                        <KpiCard 
                            title="Active Users Now" 
                            value={adminOverview?.activeUsersNow || 0} 
                            icon={Users}
                            trend={adminOverview?.trends?.users}
                            subValue="Realtime"
                        />
                        <KpiCard 
                            title="Total Reviews" 
                            value={adminOverview?.totalReviews || 0} 
                            icon={MessageSquare}
                            trend={adminOverview?.trends?.reviews}
                        />
                        <KpiCard 
                            title="Monthly Revenue" 
                            value={`₦${(adminOverview?.monthlyRevenue || 0).toLocaleString()}`} 
                            icon={CreditCard} 
                            trend={adminOverview?.trends?.revenue}
                            subValue="Last 30 days"
                        />
                    </div>

                    {/* Charts Row: User Growth & Category Breakdown */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* User Growth Chart (Chart.js) */}
                        <div className="lg:col-span-2 bg-gray-800 rounded-2xl p-6 border border-gray-700">
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="text-white font-bold text-lg">User Growth</h3>
                                <div className="text-xs text-gray-400 bg-gray-700/50 px-2 py-1 rounded">
                                    {new Date(dateRange.start).toLocaleDateString()} - {new Date(dateRange.end).toLocaleDateString()}
                                </div>
                            </div>
                            <div className="h-80 w-full">
                                {userGrowthData ? <ChartJsLineChart data={userGrowthData} /> : <div className="h-full flex items-center justify-center text-gray-500">Loading chart...</div>}
                            </div>
                        </div>

                        {/* Businesses by Category (Doughnut Chart) */}
                        <div className="bg-gray-800 rounded-2xl p-6 border border-gray-700 flex flex-col">
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="text-white font-bold text-lg">Businesses by Category</h3>
                            </div>
                            <div className="flex-1 min-h-[250px] relative">
                                {categoryChartData ? (
                                    <ChartJsDoughnutChart data={categoryChartData} />
                                ) : (
                                    <div className="h-full flex items-center justify-center text-gray-500">Loading chart...</div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Platform Growth Trends Chart (Recharts) */}
                    <div className="bg-gray-800 rounded-2xl p-6 border border-gray-700">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-white font-bold text-lg">Overall Platform Activity</h3>
                        </div>
                        <div className="h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <ComposedChart data={trendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                                    <defs>
                                        <linearGradient id="colorUsers" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.8}/>
                                            <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#374151" />
                                    <XAxis 
                                        dataKey="date" 
                                        stroke="#9CA3AF" 
                                        fontSize={12} 
                                        tickLine={false} 
                                        axisLine={false} 
                                        tickFormatter={(date) => new Date(date).getDate().toString()} 
                                    />
                                    <YAxis yAxisId="left" stroke="#9CA3AF" fontSize={12} tickLine={false} axisLine={false} />
                                    <YAxis yAxisId="right" orientation="right" stroke="#9CA3AF" fontSize={12} tickLine={false} axisLine={false} />
                                    <Tooltip 
                                        contentStyle={{ backgroundColor: '#1F2937', border: 'none', borderRadius: '8px', color: '#fff', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                                        itemStyle={{ color: '#fff' }}
                                        labelFormatter={(date) => new Date(date).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}
                                    />
                                    <Legend />
                                    <Brush dataKey="date" height={30} stroke="#EE1C47" fill="#1F2937" tickFormatter={() => ''} />

                                    <Bar yAxisId="left" dataKey="newReviews" name="New Reviews" fill="#10B981" radius={[4, 4, 0, 0]} barSize={20} />
                                    <Line yAxisId="left" type="monotone" dataKey="newUsers" name="New Users" stroke="#3B82F6" strokeWidth={2} dot={false} />
                                    <Line yAxisId="right" type="monotone" dataKey="activeBusinesses" name="Total Businesses" stroke="#8B5CF6" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                                </ComposedChart>
                            </ResponsiveContainer>
                        </div>
                    </div>

                    {/* Middle Section: Revenue & Retention */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                        {/* Revenue Bar Chart */}
                        <div className="lg:col-span-2 bg-gray-800 rounded-2xl p-6 border border-gray-700">
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="text-white font-bold text-lg">Revenue</h3>
                                <select className="bg-gray-700 border-none text-white text-xs rounded-lg px-3 py-1.5 focus:ring-0">
                                    <option>Weekly</option>
                                    <option>Monthly</option>
                                </select>
                            </div>
                            <div className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={revenueData} barSize={20}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#374151" />
                                        <XAxis dataKey="name" stroke="#9CA3AF" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                                        <YAxis stroke="#9CA3AF" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `₦${val/1000}k`} />
                                        <Tooltip 
                                            contentStyle={{ backgroundColor: '#1F2937', border: 'none', borderRadius: '8px', color: '#fff' }}
                                            cursor={{ fill: 'rgba(255,255,255,0.05)' }}
                                        />
                                        <Bar dataKey="revenue" fill="#10B981" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Retention Rate */}
                        <div className="bg-gray-800 rounded-2xl p-6 border border-gray-700 flex flex-col items-center justify-center">
                            <div className="w-full flex justify-between items-center mb-4">
                                <h3 className="text-white font-bold">Retention rate</h3>
                                <span className="bg-gray-700 text-white text-xs px-2 py-1 rounded">Weekly</span>
                            </div>
