    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  // Data State
  const [trendData, setTrendData] = useState<any[]>([]);
  const [revenueData, setRevenueData] = useState<any[]>([]);
  const [categoryData, setCategoryData] = useState<any[]>([]);
  const [retentionData, setRetentionData] = useState<any>({ rate: 0, trend: 0 });
  const [usersList, setUsersList] = useState<User[]>(MOCK_USERS_LIST);
  const [adminOverview, setAdminOverview] = useState<any>(null);
  const [userGrowthData, setUserGrowthData] = useState<any>(null);
  const [categoryChartData, setCategoryChartData] = useState<any>(null);
  const [pendingBusinesses, setPendingBusinesses] = useState<Business[]>([]);

  // Moderation State
  const [flaggedReviews, setFlaggedReviews] = useState<Review[]>([]);

  // User Search
