  const trafficSourceData = [
    { name: 'Instagram', value: 45, color: '#E1306C' },
    { name: 'Direct', value: 30, color: '#3B82F6' },
    { name: 'Google', value: 15, color: '#10B981' },
    { name: 'Referral', value: 10, color: '#F59E0B' },
  ];

  useEffect(() => {
    if (!isLoading) {
      if (!user || user.role !== 'admin') {
        navigate('/login');
        return;
      }

      // Calculate days difference for dynamic data fetching based on selected range
      const start = new Date(dateRange.start);
      const end = new Date(dateRange.end);
      const diffTime = Math.abs(end.getTime() - start.getTime());
      const daysDiff = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) || 1; 

      // Fetch Analytics with date range params
      setTrendData(analyticsService.getDashboardTrends(daysDiff));
      setRevenueData(analyticsService.getRevenueAnalytics());
      setCategoryData(analyticsService.getCategoryDistribution());
      setRetentionData(analyticsService.getRetentionStats());
      setAdminOverview(analyticsService.getAdminOverview('admin'));

      // Fetch User Growth Data for Chart.js
      // Passing daysDiff as part of the period string like '30d' to update the chart dynamically
      const growthSeries = analyticsService.getNewUsersTimeSeries('admin', `${daysDiff}d`);
      setUserGrowthData({
          labels: growthSeries.map(d => new Date(d.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })),
          datasets: [{
              label: 'New Users',
              data: growthSeries.map(d => d.count),
              borderColor: '#10B981', // Emerald 500
              backgroundColor: 'rgba(16, 185, 129, 0.1)',
              borderWidth: 2,
              fill: true,
              tension: 0.4,
              pointRadius: 4,
              pointHoverRadius: 6
          }]
      });

      // Fetch Category Distribution for Chart.js
      const categoryStats = analyticsService.getBusinessCategoryDistribution('admin');
      setCategoryChartData({
          labels: categoryStats.map(d => d.name),
          datasets: [{
              data: categoryStats.map(d => d.value),
              backgroundColor: COLORS,
              hoverOffset: 4
          }]
      });

      // Fetch Flagged Content
      setFlaggedReviews(MOCK_REVIEWS.filter(r => r.status === 'flagged'));

      // Fetch Pending Businesses
      setPendingBusinesses(MOCK_BUSINESSES.filter(b => b.verificationStatus === 'pending'));

      // Check localStorage for banned users and update initial list
      const bannedEmails = JSON.parse(localStorage.getItem('banned_users') || '[]');
      if (bannedEmails.length > 0) {
          const updatedList = MOCK_USERS_LIST.map(u => ({
              ...u,
              status: bannedEmails.includes(u.email) ? 'banned' : 'active'
